/**
 * Generated by `npm run arena:rulesets` from `src/lib/arena/rulesets/dbs/*.rules`.
 * Do not edit: edit the `.rules` file and run the script again.
 *
 * The text lives here so the loader can be pure — see the script's header.
 */
export const FILES: Record<string, string> = {
  "actions.rules": "-- The moves a player may make, as declarations rather than as predicates.\n--\n-- Sections are `docs/rules/rulemanual.txt`: §7-3-4 the free timing of the Main\n-- Phase, §7-2-11 the charge, §7-3-5 the end of the Main Phase, §0-1-3-4\n-- conceding.\n--\n-- An action is `WHEN / FOR / COST / DO / REFUSE` (§3b of\n-- `docs/arena-rules-language.md`, \"how an action is declared\" in\n-- `docs/arena-ruleset-spec.md`). `vm/actions.ts` reads all five: `WHEN` and\n-- `prompts:` say which question it is offered at, `FOR` which cards it is\n-- offered for, `REFUSE` the requirement a player is owed for each card it is\n-- *not* offered for, and `COST` and `DO` what taking it costs and does. The\n-- menu and the refusals therefore come from one paragraph, which is the whole\n-- point of the file: nothing below has a hand-written `whyNot` twin.\n--\n-- **Eight so far.** The four that need no payment and no battle came first\n-- (#145), which is what makes them the ones that proved the machinery on a real\n-- turn; the prices followed (#148), and the play family below is the first to\n-- carry one. Activating followed (#147), which is the one whose candidate is a\n-- skill *line*; the battle is Stage 6, and each arrives here as a paragraph\n-- rather than as a branch somewhere else.\n--\n-- `listed: false` is the rule the legacy engine has always had and never\n-- wrote down: a move a client shows as a button of its own is accepted\n-- without ever being enumerated. It says nothing about legality — an unlisted\n-- action is checked exactly as a listed one is — only that it is on neither\n-- the menu nor the list of refusals, because a refusal explains a move a\n-- player can see. `pass` and `concede` are the two.\n\n-- 7-2-11 gives the turn player **one** charge, and the other half of that\n-- sentence is a refusal rather than a silence: the legacy engine offers every\n-- card in hand at the Main Phase question and refuses each with \"you have\n-- already had your charge this turn\". So the move is declared in both phases\n-- and refused in one, over the player attribute §269 added for exactly this:\n-- `charged` (`attributes.rules`), true from the moment the Charge Phase's own\n-- question is answered (`vm/flow.ts`'s `mainPending`) — which is also\n-- `whyNotCharge`'s own reading (\"once the Main Phase has begun, the one\n-- charge of the turn has gone by\"), so the two engines cannot disagree about\n-- what the sentence means. Earlier this REFUSE named `asking(prompt: charge)`\n-- instead, a proxy for the fact rather than the fact itself, which is what\n-- left 13-3's `growUnison` with no word to reuse (issue #269).\nDEFINE ACTION charge                                                      -- §7-2-11\n  WHEN [charge, main]\n  prompts: [charge, main]\n  FOR 1 IN you.hand\n  BIND \"card\"\n  -- 7-2-11 is a *may*, and the half of it that takes no card is an answer of\n  -- its own rather than the absence of one: a candidate, last on the menu, so\n  -- the board keeps the ghost button beside the cards it could have charged\n  -- (`docs/arena-hud-spec.md` §2.3). The `DO` below is written about the\n  -- candidate, so declining runs it over no cards and moves nothing. It is an\n  -- answer to *this* question, so the board-level refusal below takes it off\n  -- the menu entirely at the Main Phase rather than greying it out: there is no\n  -- skip button there to explain.\n  decline: \"Skip charge\"\n  DO {\n    moveTo(target: $card, to: energy, reveal: true)\n  }\n  -- First, and about the board rather than about any card — which is the order\n  -- `whyNotCharge` asks in, so the *first* requirement a player is owed is the\n  -- same requirement on both engines, a Leader in hand included.\n  REFUSE oncePerTurn(what: \"charge\") UNLESS NOT playerAttr(name: \"charged\")\n  -- 3-1-2: a Leader Card does not leave the Leader Area, so it is not a card\n  -- this move can be made about. Nothing puts one in a hand — 6-2-1-2 places it\n  -- before the first card is drawn — which is exactly why the refusal is\n  -- declared rather than assumed away: a rule that is never reached is still\n  -- the answer a player reaching for that card is owed.\n  REFUSE cardType(needs: \"a card that is not a Leader Card\") UNLESS count(FROM $card \"non-leader card\") >= 1\n  -- 20-14: \"your opponent can't place cards in their Energy Area.\" Last, which\n  -- is `whyNotCharge`'s order again — it asks the question first and the\n  -- prohibition second. The `forbidden` requirement's own fields (which card's\n  -- rule, how long it holds, what would let it through) are the board's and are\n  -- filled in by the interpreter, because a declaration cannot name a rule that\n  -- is not in the file.\n  REFUSE forbidden() UNLESS NOT forbidden(what: placeEnergy)\n  label: \"Charge\"\n  text: \"the turn player may place 1 card from their hand in their Energy Area, face up (7-2-11)\"\n\n-- 13-3: putting another copy of the Unison Card from hand under it, once a\n-- turn, is a player attribute too (`grewUnison`, `attributes.rules`) — the\n-- same shape issue #269 gave the charge, set by this action's own `DO` rather\n-- than by a phase boundary, because unlike the charge this move either\n-- happens or it does not; there is no window that closes on its own. The\n-- per-card gate needs \"a copy of the Unison Card in play\", which the filter\n-- grammar cannot name (another card's identity is not a fixed wording) —\n-- `sameCard` reads it as two selectors instead (`vm/script-schema.ts`).\nDEFINE ACTION growUnison                                                  -- §13-3\n  WHEN [main]\n  prompts: [main]\n  FOR 1 IN you.hand\n  BIND \"card\"\n  DO {\n    moveTo(target: $card, to: under, under: IN you.unison, reveal: true)\n    addMarker(target: IN you.unison, n: 1)\n    setPlayerAttr(name: \"grewUnison\")\n  }\n  -- Board-level first, `whyNotCharge`'s own order: nothing to grow at all is\n  -- answered before whether this turn's one growth is already spent, and only\n  -- then is a particular candidate wrong.\n  REFUSE oncePerTurn(what: \"grow a Unison\") UNLESS NOT playerAttr(name: \"grewUnison\")\n  REFUSE target(reason: \"no Unison Card in play to grow\") UNLESS count(IN you.unison) >= 1\n  REFUSE cardType(needs: \"a copy of the Unison Card in play\") UNLESS sameCard(a: FROM $card, b: IN you.unison)\n  -- 7-3-4: growing a Unison is free timing, the same as `play`/`activate` —\n  -- missing here until #152 could actually complete the move to notice\n  -- (`vm/host.ts`'s `placeUnder` threw `NotYet` unconditionally before that\n  -- issue, so `setPlayerAttr` never ran and the missing `again:` had nothing\n  -- to expose: the Main Phase's own question was left on the table by the\n  -- `NotYet` itself, for the wrong reason, until now).\n  again: true\n  label: \"Grow Unison\"\n  text: \"the turn player may, once per turn, place 1 copy of their Unison Card from their hand under it, adding 1 marker (13-3)\"\n\nDEFINE ACTION endMain                                                     -- §7-3-5\n  WHEN [main]\n  prompts: [main]\n  DO {}\n  label: \"End turn\"\n  text: \"the turn player ends their Main Phase, and with it the last phase they act in (7-3-5)\"\n\nDEFINE ACTION pass                                                        -- §7-3-4\n  WHEN [setup, charge, main]\n  prompts: [mulligan, charge, main]\n  DO {}\n  listed: false\n  label: \"Pass\"\n  text: \"take none of what the question offers, whatever it is (6-2-1-9-1, 7-2-11, 7-3-4)\"\n\n-- The one move that is not an answer to the question on the table: it is taken\n-- at any point in a game, including at a prompt that belongs to the other\n-- player, and no card may cause or replace it (0-1-3-4). So `WHEN` is every\n-- phase a game is still being played in, and `prompts:` is left out.\n--\n-- Its `DO` is empty because a game *ending* is not something the effect\n-- language can say — no op of `OP_SCHEMA` ends one — so the ending stays the\n-- interpreter's, the way the steps in `vm/flow.ts`'s `STEP_WORK` are, and this\n-- declaration is what decides the move may be taken at all. A `DO` written here\n-- would be a program `vm/index.ts` refuses by name rather than ignores.\n\nDEFINE ACTION concede                                                     -- §0-1-3-4\n  WHEN [setup, charge, main, mainEnd, end]\n  DO {}\n  listed: false\n  label: \"Concede\"\n  text: \"a player gives up the game, and their opponent wins immediately (0-1-3-4)\"\n\n-- ── playing a card (§5-5, §13-2, §16-2) ───────────────────────────────────\n--\n-- Three paragraphs rather than one, because the shared `Action` union has\n-- three words: a client sends `play`, `playUnison` or `playZ`, and the\n-- declaration's **name is the action type** (`vm/actions.ts`). What they share\n-- is the `DO`: every one of them is the `play` op, which is 5-5-3's \"play this\n-- card\" — so a play a player declares and a play a skill makes are the same\n-- act, resolved in one place (`vm/play.ts`), and neither of them pends a\n-- trigger by name. The card arriving is `moved(asPlay: true)` and\n-- `triggers.rules` decides that this is `played`, `youPlayed` and\n-- `opponentPlayed`; its [Permanent]s stand because it is in an in-play area.\n--\n-- **20-14's prohibitions are read** (`forbidden()`), and each play below\n-- carries the gate: \"your opponent can't play Battle Cards\", \"this card can't\n-- be played from any area except by skills\". `bySkill: false` is the half of\n-- that wording a player's own declared play is — a play a *skill* makes is\n-- 5-5-3's, resolved by the `play` op and not by this paragraph.\n--\n-- One gate is still missing, and the language is what is missing: 22-39's\n-- [Unique] needs a filter for \"a card with the same name as *this* candidate\",\n-- which `FILTER_FIELDS` has no field for (the keyword's own body is #154's).\n--\n-- One ordering is deliberately not the legacy engine's, and is recorded rather\n-- than matched. A `REFUSE` is read **before** the price, which is where\n-- `whyNotPlay` sits for a Unison and for an X-cost card — but for a plain\n-- Battle Card `whyNotPlayFromHand` concatenates the price first, so on a board\n-- where the player is both short of energy *and* forbidden, that engine says\n-- \"1 short\" where this one says \"forbidden\". Saying a price about a move that\n-- is banned outright is the worse of the two answers, and the legacy engine\n-- already disagrees with itself about it across its own three branches\n-- (`verify/vm.ts` §21 asserts both, so neither drifts unnoticed).\n--\n-- The other half the price cannot settle is an **X cost**: 1-2-2-2 makes its\n-- value an answer to a question, and until issue #270 a candidate was a card\n-- and nothing else, so `costOf` was absent and `vm/costs.ts` refused such a\n-- card as `unread` rather than offering it free. `x: true` is the answer:\n-- one candidate per legal value of X, floored at the coloured requirement and\n-- ceilinged at what the player could pay, read generically off the price\n-- (`vm/costs.ts`'s `xValues`) rather than a branch per action. [Evolve],\n-- [Union], [Over Realm] and [Swap] are plays a keyword gates and are #157's.\n--\n-- 5-3: a card may print **another price** for playing it — \"you can play this\n-- card from your hand without paying its energy cost\", or by adding a card\n-- from life to the hand instead — which is often the only reason it is\n-- playable at all. `alt: \"play\"` is the word such a record names the move by\n-- (`altCost`'s `for:`), and a card carrying one that the board can meet is\n-- offered a second time at that price (`vm/costs.ts`' `altCostFor`), exactly\n-- as the legacy engine offers it: never for an X cost, and never past a\n-- `REFUSE` that holds.\n\nDEFINE ACTION play                                                        -- §5-5-2\n  WHEN [main]\n  prompts: [main]\n  FOR 1 IN you.hand \"battle card\"\n  BIND \"card\"\n  COST [energy]\n  x: true\n  alt: \"play\"\n  DO {\n    play(target: $card)\n  }\n  REFUSE forbidden() UNLESS NOT forbidden(what: play, bySkill: false)\n  again: true\n  label: \"Play\"\n  text: \"the turn player pays a Battle Card's energy cost and places it in their Battle Area, revealed and active (5-5-2, 3-6-3)\"\n\n-- 13-2-3: a Unison Card arrives carrying the energy that was paid for it as\n-- markers, which is what `X` is in this program — the amount the move's price\n-- was settled at (`runProgram`). A Unison printed `X` lets its master choose\n-- how many markers to buy (13-2-2), the same `x: true` enumeration `play`\n-- above declares — `x` on the Action still comes off `price.energy`\n-- (`DECLARABLE_ACTIONS`'s `cardWithX` shape, unconditional since 13-2-3), so\n-- nothing about carrying it changed, only that a Unison whose printed cost is\n-- X now reaches a price to carry at all.\nDEFINE ACTION playUnison                                                  -- §13-2\n  WHEN [main]\n  prompts: [main]\n  FOR 1 IN you.hand \"unison card\"\n  BIND \"card\"\n  COST [energy]\n  x: true\n  xMin: 1                                                                 -- 13-2-2, 3-11-3: never zero markers\n  -- 13-2-3: the markers paid for it are part of the arrival (`markers:`),\n  -- so an [Empower] carry (22-45-3, #157) lands after them, as it does on\n  -- the legacy engine.\n  DO {\n    play(target: $card, markers: X)\n  }\n  REFUSE forbidden() UNLESS NOT forbidden(what: play, bySkill: false)\n  again: true\n  label: \"Play Unison\"\n  text: \"the turn player pays a Unison Card's cost and places it in their Unison Area with that many markers, sending the Unison already there to the Drop Area (13-2, 3-11-5)\"\n\n-- 16-2 and 17-2: a Z-card is played from the Z-Deck and pays a Z-Energy price\n-- as well as its energy cost, which is why this is the one move that names two\n-- prices — in that order, because that is the order the engine that has been\n-- playing charges them in and the order is what the oracle compares.\n--\n-- 6-1-4: a Z-Leader is not played at all, it arrives through [Z-Awaken]; and\n-- 18-2's Z-Unison is a Unison, so its markers are the `x` the paragraph above\n-- says a candidate cannot carry. Both are refused here as the cards this move\n-- is not about, which is the honest answer while it is about the other two.\nDEFINE ACTION playZ                                                       -- §16-2\n  WHEN [main]\n  prompts: [main]\n  FOR 1 IN you.zDeck \"Z-card\"\n  BIND \"card\"\n  COST [zEnergy, energy]\n  DO {\n    play(target: $card)\n  }\n  REFUSE cardType(needs: \"a Z-Battle Card or a Z-Extra Card\") UNLESS any([count(FROM $card \"Z-battle card\") >= 1, count(FROM $card \"Z-extra card\") >= 1])\n  REFUSE forbidden() UNLESS NOT forbidden(what: play, bySkill: false)\n  again: true\n  label: \"Play\"\n  text: \"the turn player pays a Z-card's Z-Energy price and its energy cost and places it in their Battle Area; a Z-Extra replaces the Z-Extras already there (16-2, 17-2-1-3)\"\n\n-- ── using a skill (§9-1-2, §4-3) ────────────────────────────────────────────\n--\n-- The one move whose candidate is **a line rather than a card**, which is what\n-- `skills:` says. A card prints up to nine of them, each with its own price,\n-- its own condition and its own once-per-turn ceiling, so one being on the menu\n-- says nothing at all about the other eight: §3.2 of\n-- `docs/arena-workflow-spec.md` counts one rejection per card per action type\n-- *except* an activation, which is one per line, and this declaration is where\n-- that exception is written down rather than special-cased.\n--\n-- Three things this paragraph does that no other does, and each is read off it:\n--\n--   `skills:`  the kinds it **offers**. A line of the same family and another\n--              window — an [Activate: Battle] skill at the Main Phase question\n--              — is still a candidate, and the answer it is owed is the\n--              `timing` requirement naming the window it belongs to. The\n--              window this move offers is the one its kinds share, so the\n--              battle paragraph Stage 6 writes needs no second table.\n--   `FOR`      where the lines are read from: the three in-play areas (9-1-3-1)\n--              and the hand, because 4-2 makes using an Extra Card from the\n--              hand how an Extra is played at all. A Battle Card's line in the\n--              hand is refused with the area it is valid in.\n--   `DO {}`    deliberately empty, and checked to be: the program an activation\n--              runs is the **record's** (`card_rules.ops`, carried on\n--              `Script.ops`), and a `DO` written once here could not be the\n--              program of nine different lines. `vm/activate.ts` queues that\n--              frame on the same interpreter a pended [Auto] runs on (#142),\n--              and the moment is a `skillActivated` the declarations in\n--              `triggers.rules` answer — nothing pends a trigger by name.\n--\n-- **The price is the record's too**, which is the 8 Sep 2026 precedent applied\n-- to a move: the orbs printed in front of the line and 13-4's marker cost are\n-- what `COST` below is charged, bound from the line rather than read off the\n-- card the way a play's price is (`vm/costs.ts`'s `BoundAmounts`). `text` is\n-- the half no engine charges itself, and it is named here so that a price this\n-- engine cannot read refuses the move with `unread` instead of offering it\n-- free. The order is `marker`, then `burst` (22-27's cards off the top of the\n-- deck), then `spiritBoost` (22-43's markers off the Unison, #157), then\n-- `energy`, because that is the order the engine that has been\n-- playing charges them in, and the order is what the oracle compares.\n--\n-- **What it refuses and what it cannot.** Negation (9-1-5), the once-per-turn\n-- and [Limit X] count (22-44-3), [Bond X] and [Sparking X], 13-4's Unison Area\n-- and its one marker skill a turn, the condition 9-4 hoisted out of the price,\n-- the energy, an effect the compiler could not read, and 9-1-3-1's wrong area —\n-- in the order the legacy `whyNotActivate` asks them, so the first requirement\n-- is the same requirement on both engines. 20-14's prohibition is read too, and\n-- it is the one gate of this move that is **not** a `REFUSE` line here: the\n-- order is what matters and `whyNotActivate` asks it second, after the\n-- negation, where a declared `REFUSE` would run before everything. It is in\n-- `vm/activate.ts`'s gate list with the rest of them, at that position.\n--\n-- A keyword's own activation — [Awaken], [Evolve], [Union], [Over Realm],\n-- [Swap], [Arrival], [Successor], [Aegis], [Rejuvenate], [Overlord], [Field],\n-- [Z-Awaken] — is its `DEFINE KEYWORD`'s `DO`, offered here by `offer:`\n-- (`keywords.rules`; [Overlord] is the first, Stage 7 writes the rest one\n-- keyword at a time): the line is then a candidate of this paragraph as an\n-- `activate:main` line, with the keyword's own `REFUSE`s among its gates. A\n-- printed [Activate] line carrying a keyword whose `DO` is not written is\n-- refused `unread`, because a player reaching for it is owed an answer. An\n-- action price (4-3-3) is\n-- refused the same way and for the same reason 22-39's [Unique] is unread:\n-- the value or the identity is not a fixed wording. An X price (20-5) is\n-- issue #270's `x: true` in principle — the price is a skill line's own\n-- (`BoundAmounts`), not a card attribute `xValues` reads, so wiring it up is\n-- separate plumbing in `activate`'s own candidate builder and is not done\n-- here — it is since #439: `x: true` below makes such a line one candidate\n-- per payable X (`vm/actions.ts`'s `activation`, the legacy `xValuesFor`),\n-- and the X paid is what the effect reads as `X`. [Counter] windows are native (`vm/battle.ts`, #150), and so is\n-- this paragraph read against the combo prompt for [Activate: Battle]: the\n-- same FOR, COST and again:, asked over the battle's own two kinds.\n\nDEFINE ACTION activate                                                    -- §9-1-2\n  WHEN [main]\n  prompts: [main]\n  FOR 1 IN you.hand|leader|unison|battle|zDeck|warp                       -- zDeck: a keyword's own move only, [Z-Awaken] (22-46-5); warp: [Over Realm] only, and only while its card's [Permanent] permits it (`overRealmFromWarp`, BT31-150)\n  BIND \"card\"\n  skills: [\"activate:main\", \"activate:main/battle\"]\n  COST [marker, burst, spiritBoost, energy, zEnergy, payWith, text]       -- zEnergy: bound to 0 but from the Z-Deck (22-46-3)\n  x: true                                                                 -- 20-5: a line priced \"Pay X energy\" is offered once per payable X\n  alt: \"play\"                                                             -- 5-3, 22-37: an Extra used from the hand is played (4-2)\n  DO {}\n  again: true\n  label: \"Activate\"\n  text: \"a player uses one of a card's [Activate] skills, paying the price printed in front of it; the skill then resolves (9-1-2, 4-3-3)\"\n",
  "attributes.rules": "-- What a card and a player have, as declarations.\n--\n-- Sections are `docs/rules/rulemanual.txt`: §2 is the parts of a card, §1-2\n-- energy costs (total and specified), §1-9 the front and back sides, §1-14\n-- energy markers, §9-9-1 the order continuous effects are applied in, §20-1\n-- names a skill gives a card in all areas and §20-21 increasing or reducing\n-- an energy cost.\n--\n-- `printed: true` means the value is read off the card itself — \"the\n-- information specified on a card itself\", which §9-9-1-1 makes the base\n-- reference for everything below it. `layers:` is the order the game then\n-- applies to reach the value the rules actually use, §9-9-1 throughout:\n--   printed   the face value (9-9-1-1)\n--   rewrite   every continuous effect except those that rewrite a number\n--             (9-9-1-2)\n--   numeric   the continuous effects that rewrite a number (9-9-1-3)\n-- A cost has its own two layers because a reduction is not a rewrite of the\n-- printed cost but a discount on the price being paid (20-21): `reduction`\n-- is the flat one, `specified` the coloured one, and they move apart —\n-- `docs/arena-history-lessons.md`, 8 Sep 2026 and the owner's BT19-039\n-- ruling of 9 Sep 2026. The two therefore sit on *different* attributes:\n-- `reduction` on both halves of a price, since taking 1 off a total takes one\n-- orb with it (20-21-2), and `specified` on the coloured half alone, which is\n-- what \"moves the total nothing\" means when it is written down.\n--\n-- Where an attribute's real domain cannot be said in this grammar — `value:`\n-- knows five shapes and no enum, no union and no map — the text says what the\n-- domain is instead, and the history entry of 12 Sep 2026 records the gap\n-- rather than the file stretching to cover it.\n\n-- ── printed on the card (§2) ───────────────────────────────────────────────\n\nDEFINE ATTRIBUTE id                                                       -- §2-14\n  of: card\n  value: string\n  printed: true\n  text: \"the card number, which is what a copy limit and every reference to a card counts by (2-14, 6-1-5-1)\"\n\nDEFINE ATTRIBUTE name                                                     -- §2-3\n  of: card\n  value: string\n  printed: true\n  face: true\n  text: \"the card name (2-3); a Leader's back reads its awakened side's own name once flipped (1-9, 10-1-3), the owner's face-showing ruling of 20 Sep 2026 (issue #327)\"\n\nDEFINE ATTRIBUTE type                                                     -- §2-1\n  of: card\n  value: string\n  printed: true\n  text: \"the card type, one of LEADER, BATTLE, EXTRA, UNISON, Z-LEADER, Z-BATTLE, Z-EXTRA, Z-UNISON and TOKEN (2-1, 10 to 19)\"\n\nDEFINE ATTRIBUTE colors                                                   -- §2-2\n  of: card\n  value: colors\n  printed: true\n  face: true\n  text: \"the card's colors: red, blue, green, yellow, black, white, or none of them (1-8, 2-2); the face-showing ruling of 20 Sep 2026 (issue #327) names this one, though the catalog has never recorded a Leader's back printing a different colour from its front\"\n\nDEFINE ATTRIBUTE energyCost                                               -- §2-5\n  of: card\n  value: number\n  printed: true\n  face: true\n  text: \"the total cost of playing the card from hand; an X cost is a number its master chooses when it is paid and zero at every other time (1-2-2, 1-2-2-2); the face-showing ruling of 20 Sep 2026 (issue #327) names every cost, though a Leader — the only card with a back to flip to — has none of this to read on either face\"\n\nDEFINE ATTRIBUTE specifiedCost                                            -- §1-2-3\n  of: card\n  value: colors\n  printed: true\n  layers: [printed, reduction, specified]\n  face: true\n  text: \"the coloured orbs of the energy cost, one entry per orb, that must be matched in colour when the cost is paid (1-2-3, 5-3); a flat reduction takes an orb off with each energy it takes off the total (20-21-2), and the `specified` layer is the half that relaxes or tightens the colours alone without moving the total at all; the face-showing ruling of 20 Sep 2026 (issue #327) names this among the costs\"\n\nDEFINE ATTRIBUTE zEnergyCost                                             -- §2-6\n  of: card\n  value: number\n  printed: true\n  face: true\n  text: \"the Z-Energy cost of playing the card from the Z-Deck (1-4, 2-6); the face-showing ruling of 20 Sep 2026 (issue #327) names every cost\"\n\nDEFINE ATTRIBUTE power                                                    -- §2-7\n  of: card\n  value: number\n  printed: true\n  layers: [printed, rewrite, numeric]\n  face: true\n  text: \"the number a battle is decided by (2-7, 8-4); combo power is added to it only in the Damage Step (5-7); read off the face showing since #166's pre-flip review, and named again by the owner's face-showing ruling of 20 Sep 2026 (issue #327)\"\n\n-- 20-3-1 — the printed face value, said on its own so that nothing has to\n-- read it back off `power` once 9-9-1's layers have been applied to that one.\n-- It has no `CardDef` field of its own (`vm/cards.ts`'s `CATALOG` is keyed by\n-- one), because the face showing is not the catalog row: a flipped Leader\n-- answers with its awakened side and a card in Hidden Mode with nothing at all\n-- (1-9, 23-5-2), which is `vm/program.ts`'s `facePower` and the legacy\n-- `face()`. `layers: [printed]` is what says the board fills it and no layer\n-- moves it — the same shape `mode` and `markers` below take. It carries no\n-- `face:` of its own for exactly that reason: `face:` says \"overlay the shown\n-- face onto the catalog's printed value\", and this attribute has no catalog\n-- value to overlay in the first place — `power` and this one are the two\n-- `attrsNow` fills entirely through the shown-face helper, the pattern every\n-- other `face: true` attribute below now shares (issue #327).\nDEFINE ATTRIBUTE originalPower                                            -- §20-3-1\n  of: card\n  value: number\n  printed: false\n  layers: [printed]\n  text: \"the power printed on the face this card is showing, before any skill effect has applied (20-3-1); a Hidden Mode card has none to read at all (23-5-2)\"\n\nDEFINE ATTRIBUTE comboCost                                                -- §2-9\n  of: card\n  value: number\n  printed: true\n  face: true\n  text: \"the energy paid to use the card in a combo (2-9, 5-6); the face-showing ruling of 20 Sep 2026 (issue #327) names every cost\"\n\nDEFINE ATTRIBUTE comboPower                                               -- §2-8\n  of: card\n  value: number\n  printed: true\n  layers: [printed, rewrite, numeric]\n  face: true\n  text: \"the power the card adds when it is used in a combo (2-8, 5-7); the face-showing ruling of 20 Sep 2026 (issue #327) reads this off the face showing alongside `power`\"\n\nDEFINE ATTRIBUTE characters                                               -- §2-10\n  of: card\n  value: strings\n  printed: true\n  text: \"the character names the card carries, written in angle brackets (2-10)\"\n\nDEFINE ATTRIBUTE traits                                                   -- §2-11\n  of: card\n  value: strings\n  printed: true\n  face: true\n  text: \"the special traits the card carries, written in double angle brackets (2-11); the face-showing ruling of 20 Sep 2026 (issue #327) names this one, though the catalog has never recorded a Leader's back printing traits its front does not\"\n\nDEFINE ATTRIBUTE skill                                                    -- §2-4\n  of: card\n  value: string\n  printed: true\n  face: true\n  text: \"the card's text box, which is every skill it has before any is gained or negated (2-4, 1-5); a Leader's back reads its awakened side's own text once flipped (1-9, 10-1-3), the owner's face-showing ruling of 20 Sep 2026 (issue #327)\"\n\nDEFINE ATTRIBUTE back                                                     -- §1-9\n  of: card\n  value: boolean\n  printed: true\n  text: \"whether the card has a back side to turn to — a Leader's awakened face, or a Z-Leader's single face (1-9). What is printed on that face is a face of its own, which this grammar still has no kind for (see the history entry of 12 Sep 2026) — `face: true` on the attributes above is the smaller answer the owner's ruling of 20 Sep 2026 (issue #327) settled on instead: every attribute that ruling names is read off the face showing rather than off this boolean's own card row, and `CardDef.back` is still the only place a distinct back value can actually be recorded (`name`, `power`, `skill`)\"\n\nDEFINE ATTRIBUTE alsoNames                                                -- §20-1\n  of: card\n  value: strings\n  printed: false\n  text: \"the card names a skill gave this card in all areas; it answers to these as well as to its printed name, never instead of it (20-1)\"\n\n-- 1-5-9 / 9-1-4 — what a filter's bare \"skill-less\" asks. Not `skill`, which\n-- is the printed text box: a card whose every skill is negated is treated as\n-- skill-less (9-1-4), and one that has gained or copied a skill (20-18) has\n-- one. `attrsNow` works it out off the table, the way `alsoNames` above is\n-- filled from the effects in force rather than from the catalog row.\nDEFINE ATTRIBUTE skillLess                                                -- §1-5-9, §9-1-4\n  of: card\n  value: boolean\n  printed: false\n  text: \"whether the card has no skill in force: none printed, or every one negated (9-1-4), and none granted or copied; a Hidden Mode card has no text to read (23-5-2)\"\n\n-- ── a card's state on the table (spec §2.5-1/§2.5-3, #275) ─────────────────\n--\n-- `modifyAttr` reached one card and six attributes before this issue\n-- (docs/arena-ruleset-spec.md §2.5-1); these are the six the compiler's own\n-- `switchMode`, `addMarker`/`removeMarker`, `grant`, `hidden`, `faceUp` and\n-- `flip` already write, declared so the primitive can reach them too and\n-- `vm/effects.ts` has a layer order to read them through. None has a printed\n-- face on the catalog row — each starts at a rules-given default and is\n-- changed directly, on the card sitting on the table, never by a continuous\n-- effect with a duration — so `layers: [printed]` alone is the honest\n-- declaration for five of them: the \"printed\" layer is not the catalog, it\n-- is whatever the table currently says. `keywords` is the one exception,\n-- because a keyword actually is granted for a duration (13-4's marker\n-- skills, most [Auto]/[Activate] \"gains [X]\" text) as well as standing from\n-- a [Permanent] — the `rewrite`/`numeric` split 9-9-1 already draws for\n-- `power`. What a granted keyword then *does* is Stage 7's hook contract\n-- (#153-#157), out of scope here; this attribute only says which names are\n-- in force.\n\nDEFINE ATTRIBUTE mode                                                     -- §1-10\n  of: card\n  value: string\n  printed: false\n  layers: [printed]\n  text: \"Active Mode or Rest Mode (1-10). Switched directly (`switchMode`), never by a continuous effect, so the printed layer is the only one — read fresh off the card on the table and nowhere else\"\n\nDEFINE ATTRIBUTE markers                                                  -- §1-11\n  of: card\n  value: number\n  printed: false\n  layers: [printed]\n  text: \"the markers on this card (1-11), changed directly (`addMarker`/`removeMarker`) and never by a continuous effect with a duration, so the printed layer is the only one. Energy markers are a player's, not a card's — `energyMarkers` below (1-14)\"\n\nDEFINE ATTRIBUTE keywords                                                 -- §9-1-3, §22-1\n  of: card\n  value: strings\n  printed: false\n  layers: [printed, rewrite, numeric]\n  text: \"the keyword names in force: the printed ones, a [Permanent]'s standing grant (rewrite, 9-9-1-2) and a resolved skill's own grant for a duration (numeric, 9-9-1-3) unioned in. A negated keyword is read where a skill is negated at all (9-1-5), not through this attribute\"\n\nDEFINE ATTRIBUTE hidden                                                   -- §23-5\n  of: card\n  value: boolean\n  printed: false\n  layers: [printed]\n  text: \"Hidden Mode (face down in play, no information) or Revealed Mode (23-5). Switched directly, never by a continuous effect, so the printed layer is the only one — read fresh off the card on the table\"\n\nDEFINE ATTRIBUTE faceUp                                                   -- §3-9-2-1\n  of: card\n  value: boolean\n  printed: false\n  layers: [printed]\n  text: \"whether a card in a closed area — a Life Area — has been turned face up (3-9-2-1). Switched directly, never by a continuous effect, so the printed layer is the only one — read fresh off the card on the table\"\n\nDEFINE ATTRIBUTE flipped                                                  -- §1-9, §22-2-4\n  of: card\n  value: boolean\n  printed: false\n  layers: [printed]\n  text: \"whether the card has turned to its back side — a Leader's awakened face (1-9, 22-2-4). Switched directly, never by a continuous effect, so the printed layer is the only one — read fresh off the card on the table\"\n\n-- ── what the board makes of them (§9-9-1, §20-21) ──────────────────────────\n\nDEFINE ATTRIBUTE costOf                                                   -- §20-21\n  of: card\n  value: number\n  printed: false\n  layers: [printed, reduction]\n  text: \"the total price of playing this card as it stands: the printed total cost, less every cost reduction in force, and never less than zero (20-21-1, 20-21-2). The coloured half of the same price is `specifiedCost`, which carries the `specified` layer, because a sentence that relaxes which colours are demanded moves the total nothing at all — the owner's BT19-039 ruling of 9 Sep 2026\"\n\nDEFINE ATTRIBUTE comboCostOf                                              -- §20-21\n  of: card\n  value: number\n  printed: false\n  layers: [printed, reduction]\n  text: \"the combo cost as it stands, after every reducer in force, and never less than zero (5-7-3, 20-21-2)\"\n\nDEFINE ATTRIBUTE zEnergyCostOf                                            -- §20-21\n  of: card\n  value: number\n  printed: false\n  layers: [printed, reduction]\n  text: \"the Z-Energy cost as it stands, after every reducer in force, and never less than zero (5-4, 20-21-2)\"\n\n-- ── what a player has (§1-14) ──────────────────────────────────────────────\n\nDEFINE ATTRIBUTE energyMarkers                                            -- §1-14\n  of: player\n  value: number\n  printed: false\n  text: \"the energy markers in a player's Energy Area: each pays one energy of the Leader's colour, and neither is a card nor is energy (1-14-1, 1-14-2, 1-14-3)\"\n\n-- These two are facts about a player rather than about the board, which is\n-- the gap #145's charge and #157's growUnison were left standing on: 7-2-11's\n-- one charge and 13-3's one Unison growth are each a player having \"already\n-- had\" one this turn, and until now the language had no word for that,\n-- letting the charge's `REFUSE` only borrow a proxy word instead\n-- (`asking(prompt: charge)`, which said which question was on the table\n-- rather than the fact itself). `reset: turnStart` is the ceiling, read by\n-- `vm/flow.ts`'s `endTurn` off the declaration rather than picked out of it\n-- by name — the same promise `LIMIT n` on a step makes for a repeat (issue\n-- #269).\n\nDEFINE ATTRIBUTE charged                                                  -- §7-2-11\n  of: player\n  value: boolean\n  printed: false\n  reset: turnStart\n  text: \"whether this player has had their one charge this turn (7-2-11); true from the moment the Charge Phase's own question is answered, charging or not, since that is the only opportunity this engine offers one at\"\n\nDEFINE ATTRIBUTE grewUnison                                               -- §13-3\n  of: player\n  value: boolean\n  printed: false\n  reset: turnStart\n  text: \"whether this player has already grown their Unison Card this turn (13-3); set the moment growUnison resolves\"\n\n-- A counted fact of the same kind (#157): [Over Realm] and [Dark Over Realm]\n-- share one activation a turn, two with [Wormhole] (22-15-3, 22-24), so the\n-- uses are counted rather than flagged. Rests at 0 at the start of the turn.\nDEFINE ATTRIBUTE overRealms                                               -- §22-15\n  of: player\n  value: number\n  printed: false\n  reset: turnStart\n  text: \"how many times this player has activated [Over Realm] or [Dark Over Realm] this turn (22-15-3); one more each time\"\n\n-- ── the battle in progress (§8-1, §22-4-2, #328) ────────────────────────────\n--\n-- `modifyAttr` reached a second widened subject alongside the player\n-- (spec §2.5-1): the battle in progress, which has one attribute and needs no\n-- locator of its own since there is only one (`redirectAttack`'s own\n-- `docs/arena-ruleset-spec.md` §2.3 row). Declared here, like `energyMarkers`\n-- above, so the loader's attribute check (#328) has something to resolve\n-- `attr: guard` against — nothing reads this declaration's `value`/`printed`\n-- the way a card or player attribute's are read; `redirectAttack` is the one\n-- op that ever writes it, straight onto the battle rather than through a\n-- layer.\n\nDEFINE ATTRIBUTE guard                                                    -- §8-1, §22-4-2\n  of: battle\n  value: ref\n  printed: false\n  text: \"the current target of the attack in progress, switched by a redirect (8-1, 22-4-2); the battle in progress has only one, so modifyAttr reads this as the value being set rather than a locator\"\n",
  "battle.rules": "-- The battle (8-1 … 8-5): attacker and guard, the blocker and counter windows,\n-- the offense and defense combo offers, the damage, and the end of the fight.\n--\n-- Sections are `docs/rules/rulemanual.txt` §8. `attack` itself is not\n-- declared here as a `DEFINE ACTION` — every other action `actions.rules`\n-- declares is a player and at most one card (`vm/actions.ts`'s own limit,\n-- recorded on its `Candidate` type), and an attack is a player and *two*\n-- cards, an attacker and a target. `block` and `counter` have a second reason\n-- to stay native: their `Prompt` shapes freeze a candidate list onto the\n-- question the moment it is raised (the legacy engine's own shapes,\n-- `{kind:\"blocker\",candidates}` and `{kind:\"counter\",window,candidates}`),\n-- which is not what a live `FOR` selector does. `vm/battle.ts` is the whole\n-- of that — read its own header before this file, since the two are one\n-- piece of work read in two places.\n--\n-- What *is* declared here, and is the real reason this is a `.rules` file and\n-- not only TypeScript: the battle's own phase and the nine steps that make it\n-- up, in 8-1 … 8-5's order, read by the exact same `vm/flow.ts` runner a\n-- turn's phases are — a stack of frames, a step's `LIMIT`, a checkpoint\n-- between each. `battle` is deliberately **not** one of `DEFINE GAME`'s\n-- `phases:` (`game.rules`): a turn's phases are a sequence `phaseAfter` walks,\n-- and a battle is not the Main Phase's successor, it is a frame **nested**\n-- inside it — pushed by `vm/battle.ts`'s `declareAttack` with the same\n-- `enterPhase` a turn phase uses, and popped by the runner's own fallback\n-- (`vm/flow.ts`: a phase with no successor and a frame still beneath it\n-- simply resumes reading that frame) the moment its steps run out. No change\n-- to the runner was needed for the nesting itself — only for the two windows\n-- whose question is not one of the four `PROMPT_ASKS` already knows how to\n-- put (`Work.run` returning `\"wait\"`, #150's one addition, documented where\n-- it is made).\n--\n-- None of these nine steps carries a `DO`: every one is worked natively in\n-- `vm/battle.ts`'s `BATTLE_STEP_WORK`, the same honest gap `flow.ts`'s own\n-- `STEP_WORK` documents for the turn's machinery — a step here is complete\n-- except for the program, and the day one is added is the day the row in\n-- that table is deleted rather than grown a tenth entry.\n\nDEFINE PHASE battle                                                       -- §8-1\n  steps: [battleDeclare, battleCounterAttack, battleBlocker, battleOffense, battleOffenseCombo, battleDefense, battleDefenseCombo, battleDamage, battleEnd]\n  auto: true\n  announce: false\n  text: \"an attacker and a guard fight it out: declared, blocked or countered, a combo offered on each side, and the higher power wins (8-1 … 8-5)\"\n\nDEFINE STEP battleDeclare                                                 -- §8-1-2, 8-1-3\n  phase: \"battle\"\n  optional: false\n  text: \"the attack is declared: the attacker and the target are named, and 'when this card attacks'/'when this card is attacked' pend (8-1-2, 8-1-3)\"\n\nDEFINE STEP battleCounterAttack                                           -- §8-1-4, 9-7\n  phase: \"battle\"\n  optional: false\n  text: \"the window after an attack is declared: the defending player may activate a [Counter: Attack] or [Counter: Battle Card Attack] skill from hand (8-1-4, 9-7)\"\n\nDEFINE STEP battleBlocker                                                 -- §8-1-2-1, 22-4\n  phase: \"battle\"\n  optional: false\n  text: \"the defending player may activate one [Blocker] card's keyword, making it the guard in the original target's place (8-1-2-1, 22-4)\"\n\nDEFINE STEP battleOffense                                                 -- §8-2\n  phase: \"battle\"\n  optional: false\n  text: \"the Offense Step begins: 'at the start of the offense step' pends for the attacking player's cards (8-2, 8-2-2)\"\n\nDEFINE STEP battleOffenseCombo                                            -- §5-7, 8-2-4\n  phase: \"battle\"\n  optional: false\n  text: \"the attacking player may add cards to their Combo Area, one at a time, paying each one's combo cost (5-7, 8-2-4)\"\n\nDEFINE STEP battleDefense                                                 -- §8-3\n  phase: \"battle\"\n  optional: false\n  text: \"the Defense Step begins, skipped outright when the guard is a Unison (8-2-4-3-1-1): 'at the start of the defense step' pends for the guarding player's cards (8-3, 8-3-2)\"\n\nDEFINE STEP battleDefenseCombo                                            -- §5-7, 8-3-4\n  phase: \"battle\"\n  optional: false\n  text: \"the guarding player may add cards to their Combo Area the same way (5-7, 8-3-4)\"\n\nDEFINE STEP battleDamage                                                  -- §8-4\n  phase: \"battle\"\n  optional: false\n  text: \"power is compared, combo power included, and the loser's Battle Card is KO'd, a Unison loses a marker, or a Leader takes damage (8-4-4 … 8-4-6)\"\n\nDEFINE STEP battleEnd                                                     -- §8-5\n  phase: \"battle\"\n  optional: false\n  text: \"the Battle End Step: 'at the end of the battle' pends, every combo card goes to the Drop Area, and the battle closes (8-5)\"\n",
  "costs.rules": "-- What a move costs, as declarations rather than as branches of one search.\n--\n-- Sections are `docs/rules/rulemanual.txt`: §5-3 paying an energy cost and\n-- §8-3-2-3 doing it in the Main Phase, §1-2-3 the specified (coloured) half of\n-- a cost, §1-14-2 energy markers standing in for energy of the Leader's\n-- colour, §3-8-2 the player's free choice of which energy to rest, §13-4 a\n-- Unison's marker cost, §20-5 an X price, §20-19 a card rested in the Energy\n-- Area's place, §21-3 life as a price, §22-27 [Burst X], and §22-30 [Warrior\n-- of Universe 7].\n--\n-- In the legacy engine payment is one function, `planPayment` in\n-- `engine/state.ts`, with a branch inside it for each of those: the coloured\n-- orbs, the either-orbs, X, the cards that may stand in for energy, and\n-- [Warrior of Universe 7] clearing the colours outright. It plays this game\n-- correctly and it can only ever play this game — a second game with a\n-- different resource has nowhere to say so. Here each is a `DEFINE COST`, and\n-- `vm/costs.ts` is one planner over the **declared** kinds (#148).\n--\n-- Two lines carry the whole of what an interpreter needs to charge a price it\n-- has never seen:\n--\n--   `consumes:`  the resource it takes — `energy`, `markers`, `life`, `mode`,\n--                `cards`, or `unreadable` for the half of a printed price no\n--                engine can charge itself. The planner switches on this word\n--                and never on the declaration's *name*, so a second game's\n--                `DEFINE COST mana / consumes: energy` is charged by the same\n--                search this file's `energy` is.\n--   `amount:`    the **card attribute** the price's amount is read off, when\n--                the move asking for it names a card (§20-21). `ACTION play\n--                COST [energy]` passes no arguments, so the number comes from\n--                the card being paid for, and this line is where the game says\n--                which number that is. It names the *derived* attribute\n--                (`costOf`, never `energyCost`), so every reduction in force\n--                reaches a play's price through the declared `layers:` rather\n--                than through a second path.\n--   `asks:`      how the payment puts its question (§3-8-2). `choice` is a\n--                price the payer is asked about whenever more than one\n--                genuinely different way to pay it exists — which is the\n--                `payCost` prompt the board already answers; `nothing` is a\n--                price with only ever one way to pay, which is settled without\n--                a question.\n--\n-- The `DO` program says two things at once, and both are read: its **target**\n-- is the pool the price is paid out of (the active cards in your Energy Area,\n-- the cards in your life), and the **op** is what paying does to what was\n-- taken from it. How *many* is the price's own amount and is never in the\n-- program — an action asks for a price by name and the amount comes off the\n-- card being paid for.\n--\n-- Two gaps are written here rather than papered over. `TAKES` names what each\n-- price is given, but `ACTION ... COST [energy]` passes no arguments, so where\n-- the values come from is the *thing being paid for*: a price paid for a card\n-- reads its amount off the card through `amount:` above, and a price paid for a\n-- **skill line** has it bound in by the interpreter that knows which line it is\n-- (#147, `vm/costs.ts`'s `BoundAmounts`) — which is where `marker`, `life` and\n-- `payWith` get their numbers and `text` gets bound away on a skill whose whole\n-- cost is orbs (#149: `activate`'s own `payWith` items, resolved off the\n-- record and rested where they stand). What still has nothing to bind it is\n-- the *[Permanent]* form of the same permission — \"you can use this card to\n-- pay energy costs even when it's in your Battle Area\" (BT3-039) — grants a\n-- payer to the whole board rather than to one price, so it is not bound to any\n-- price at all: `vm/effects.ts`' `permanents` collects it as a standing\n-- `payer`, and `vm/costs.ts`' `payersFor` adds it to the pool of *every*\n-- energy price, the legacy `payersFor`'s reading. And an **either-orb** (\"{Red/Blue}\", one orb payable with any one of the\n-- listed colours, §22-13) has no parameter type that can name it: `colors` is a\n-- flat list and the language knows no list of alternatives. The planner reads them off the price\n-- and charges them exactly; the parameter list below cannot say so, the way\n-- `attributes.rules` cannot say what is printed on a card's back side.\n\nDEFINE COST energy                                                        -- §5-3\n  TAKES (total: amount, orbs: colors, x: amount)\n  consumes: energy\n  amount: \"costOf\"\n  asks: choice\n  DO {\n    switchMode(target: IN you.energy active, mode: rest)\n  }\n  text: \"the price is paid by switching that many active cards in your Energy Area to Rest Mode, the coloured orbs matched in colour; an energy marker pays one energy of your Leader's colour in a card's place (5-3-3, 1-2-3, 1-14-2)\"\n\n-- The other half of a Z-card's price (§5-4). It is a `cards` price like\n-- `payWith` below and the planner tells the two apart the way it tells any two\n-- prices apart — by reading the `DO`, never the name: this one's target names\n-- a **place** (`IN you.zEnergy`), so the cards come out of that pool and go\n-- where the op says; `payWith`'s names cards the price was handed, so they are\n-- rested where they stand. 5-4-3: the Z-Energy is spent, not rested — the\n-- cards are placed in the Drop Area — which is why the op is a move.\n-- `fromEnd` says which end of the pile the cards come off: the far end, the\n-- last placed first, which is the order the engine that has been playing\n-- spends Z-Energy in and therefore the order the Drop Area ends up in.\nDEFINE COST zEnergy                                                       -- §5-4\n  TAKES (n: amount)\n  consumes: cards\n  amount: \"zEnergyCostOf\"\n  asks: nothing\n  DO {\n    moveTo(target: IN you.zEnergy fromEnd, to: drop)\n  }\n  text: \"a Z-card's Z-Energy price: that many cards are placed from the Z-Energy Area in the Drop Area, on top of the card's energy cost (5-4, 16-2-1)\"\n\n-- [Burst X] (§22-27) is a price written as a tag in front of a skill: the top\n-- X cards of your deck are placed in your Drop Area, and with fewer than X\n-- cards in the deck it cannot be paid (22-27-3). It is a `cards` price out of\n-- a declared place like `zEnergy` above, read the same way — the pool is the\n-- op's target and paying does what the op says — with two differences, both\n-- read off the declaration rather than the name: the cards come off the\n-- **top** (no `fromEnd`), and the amount is not an attribute of the card,\n-- because a card prints a [Burst] on one skill line and not on itself. So it\n-- names no `amount:`, and the interpreter that knows which line is being\n-- paid for binds the number in (`vm/activate.ts`'s `boundFor`, #148), the way\n-- `marker` and `life` below get theirs. The deck is a hidden zone, so each\n-- card is shown as it goes.\nDEFINE COST burst                                                         -- §22-27\n  TAKES (n: amount)\n  consumes: cards\n  asks: nothing\n  DO {\n    moveTo(target: IN you.deck, to: drop)\n  }\n  text: \"the price is paid by placing that many cards from the top of your deck in your Drop Area, each shown as it goes; with fewer cards in the deck it cannot be paid (22-27-2, 22-27-3)\"\n\nDEFINE COST marker                                                        -- §13-4\n  TAKES (n: amount)\n  consumes: markers\n  asks: nothing\n  DO {\n    addMarker(target: [self], n: $n)\n  }\n  text: \"the price is paid with the markers on the card whose skill is being used: a negative number removes that many, and the card may use no further marker skill this turn (13-4, 1-11)\"\n\n-- [Spirit Boost X] (§22-43) is a marker price like 13-4's, written as a tag in\n-- front of a skill — but the markers come off the Unison Card in the Unison\n-- Area, not off the card whose skill is used. The planner reads which card\n-- from the op's target, as it reads a pool for `burst`: `[self]` is the card\n-- itself, a place is the card in it. The amount is the line's (the tag's X,\n-- negative to remove), bound by the activation (#157); the shortfall is asked\n-- among the activation's gates, beside [Burst]'s, in the legacy words.\nDEFINE COST spiritBoost                                                   -- §22-43\n  TAKES (n: amount)\n  consumes: markers\n  asks: nothing\n  DO {\n    addMarker(target: IN you.unison, n: $n)\n  }\n  text: \"the price is paid by removing that many markers from your Unison Card; with fewer on it, it cannot be paid (22-43-2)\"\n\nDEFINE COST life                                                          -- §21-3\n  TAKES (n: amount)\n  consumes: life\n  asks: nothing\n  DO {\n    moveTo(target: IN you.life, to: drop)\n  }\n  text: \"the price is paid by placing that many cards from your life in your Drop Area (21-3)\"\n\nDEFINE COST rest                                                          -- §8-4-1\n  TAKES ()\n  consumes: mode\n  asks: nothing\n  DO {\n    switchMode(target: [self], mode: rest)\n  }\n  text: \"the price is paid by switching the card itself to Rest Mode, which a card already in Rest Mode cannot do (1-10-1)\"\n\nDEFINE COST payWith                                                       -- §20-19\n  TAKES (cards: selector)\n  consumes: cards\n  asks: choice\n  DO {\n    switchMode(target: FROM $cards, mode: rest)\n  }\n  text: \"cards outside the Energy Area that this price may be paid with instead, each rested where it stands and counting as energy of the colours the price says (20-19)\"\n\n-- The price the engine does not charge, and the reason it is a declaration at\n-- all: a move whose price has no `DEFINE COST` would be offered for free, and\n-- a move whose price is *declared unreadable* is refused with an `unread`\n-- requirement naming the card — the same answer the legacy engine gives for a\n-- skill whose cost the compiler could not read.\nDEFINE COST text                                                          -- §4-3-3\n  TAKES (printed: string)\n  consumes: unreadable\n  asks: nothing\n  DO {}\n  text: \"the price as printed, kept for the part no engine can charge itself; a move that asks for it is refused rather than offered free (4-3-3)\"\n",
  "game.rules": "-- The Dragon Ball Super Card Game itself: how a player starts, what a turn is\n-- made of, and how the game ends.\n--\n-- Sections are `docs/rules/rulemanual.txt`: §0-1-3 ending the game, §6-1 the\n-- Leader Card and the decks, §6-2 pre-game preparations, §7-1 the turn,\n-- §7-2 the Charge Phase, §7-3 the Main Phase, §7-4 the End Phase.\n--\n-- Three things the manual says here that the grammar has no field for are\n-- left out rather than written wrongly, and each is recorded in the history\n-- entry of 12 Sep 2026:\n--   * the deck is 50 **to 60** cards (6-1-3) and a Z-Deck is **up to** 10\n--     (6-1-4) — `deck:` and `zDeck:` are one number each, so they are read\n--     below as the deck's minimum and the Z-Deck's maximum;\n--   * a deck may hold up to 4 copies of a card number (6-1-5-1) — there is no\n--     field for a copy limit;\n--   * only the player who goes **second** places an energy marker (6-2-1-11)\n--     — `startMarkers:` is one number for both players, so it is left out and\n--     the setup step below is where that rule is said.\n\nDEFINE GAME dbs                                                           -- §6-1\n  title: \"Dragon Ball Super Card Game\"\n  players: 2\n  deck: 50\n  zDeck: 10\n  hand: 6\n  life: 8\n  mulligan: true\n  firstPlayerDraws: false\n  phases: [charge, main, mainEnd, end]\n  setupPhase: \"setup\"\n  overPhase: \"over\"\n\n-- ── the phases ────────────────────────────────────────────────────────────\n--\n-- A turn is three phases, each made of steps, and a phase or a step exists\n-- even when nothing happens in it (7-1-1). `setup` and `over` are not phases\n-- of a turn: they are the pre-game procedure (6-2) and the end of the game\n-- (0-1-3), which this engine runs as phases of their own and which is why\n-- `DEFINE GAME`'s `phases:` above lists four names and not six. They are\n-- named instead by `setupPhase:` and `overPhase:`, so the flow runner knows\n-- where a game begins and where it comes to rest without knowing either word\n-- (#140).\n--\n-- `announce:` is whether entering a phase is a moment of its own in the log —\n-- the beat the board narrates. Three of the six are announced, which is what\n-- the engine that has been playing announces: the Main Phase End Step passes\n-- inside the Main Phase as far as a player is concerned (7-3-5), and neither\n-- the pre-game procedure nor the finished game is a phase of a turn at all.\n--\n-- The manual makes the Main Phase End Step a step of the Main Phase\n-- (7-3-5); this engine has run it as a phase of its own since before the\n-- rules language existed, so it is declared as one here. The history entry of\n-- 12 Sep 2026 records the difference.\n--\n-- `skip:` is 20-13: the word a skill's `skip` entry names the phase by. A\n-- skipped phase is announced as skipped and then not performed (20-13-1..4),\n-- except for the steps declared `always:` — a continuous effect that ends in\n-- a phase ends when it is skipped (20-13-5), and the turn still passes at the\n-- end of a skipped End Phase. The Main Phase End Step says `skip: main` too,\n-- so a skipped Main Phase takes it along, as the manual's own 7-3-5 has it.\n-- The battle's Offense and Defense Steps are skipped by `vm/battle.ts`'s own\n-- native step work, beside the rest of what that work still does natively.\n--\n-- `actions:` is left off every phase: the moves a player may declare (7-3-4)\n-- are `DEFINE ACTION`s, and the loader refuses a phase naming one that\n-- nothing declares. They arrive with `play.rules`.\n\nDEFINE PHASE setup                                                        -- §6-2\n  steps: [setupPresent, setupLeader, setupLeaderPending, setupFirstPlayer, setupShuffle, setupZDeck, setupHand, setupMulligan, setupLife, setupEnergyMarker, setupStart]\n  auto: false\n  announce: false\n  text: \"the pre-game procedure, before the first turn: leaders down, first player chosen, hands drawn and life set out (6-2-1)\"\n\nDEFINE PHASE charge                                                       -- §7-2\n  steps: [chargeTurnEffects, chargeContinuousEnd, chargePending, chargeActivate, chargeDraw, chargeEnergy]\n  auto: false\n  announce: true\n  skip: charge\n  text: \"the rules processing at the start of a turn, with a checkpoint after each step (7-2-1, 7-2-6, 7-2-8, 7-2-10, 7-2-12)\"\n\nDEFINE PHASE main                                                         -- §7-3\n  steps: [mainPending, mainActions]\n  auto: false\n  announce: true\n  skip: main\n  text: \"the phase the turn player takes their moves in, returning to a checkpoint after each one (7-3-1, 7-3-4)\"\n\nDEFINE PHASE mainEnd                                                      -- §7-3-5\n  steps: [mainEndPending, mainEndEffects]\n  auto: true\n  announce: false\n  skip: main\n  text: \"the Main Phase End Step, which the manual counts as a step of the Main Phase and this engine runs as a phase (7-3-5)\"\n\nDEFINE PHASE end                                                          -- §7-4\n  steps: [endPending, endRepeat, endEffects, endTurn]\n  auto: true\n  announce: true\n  skip: end\n  text: \"the end of the turn: what answers to it is made pending, what lasted for the turn ends, and the other player becomes the turn player (7-4-1, 7-4-7)\"\n\nDEFINE PHASE over                                                         -- §0-1-3\n  steps: [gameEnd]\n  auto: true\n  announce: false\n  text: \"the game is over, which is not a phase of a turn: a player has lost and nothing further is played (0-1-3)\"\n\n-- ── setup (§6-2-1) ────────────────────────────────────────────────────────\n\nDEFINE STEP setupPresent                                                  -- §6-2-1-1\n  phase: \"setup\"\n  optional: false\n  text: \"each player presents the Leader Card, deck and Z-Deck they will use, which must meet the deck construction rules (6-2-1-1, 6-1)\"\n\nDEFINE STEP setupLeader                                                   -- §6-2-1-2\n  phase: \"setup\"\n  optional: false\n  text: \"each player places their Leader Card front side up in their Leader Area (6-2-1-2)\"\n\nDEFINE STEP setupLeaderPending                                            -- §6-2-1-3\n  phase: \"setup\"\n  optional: false\n  text: \"trigger conditions for \\\"when this card is placed in a Leader Area\\\" skills enter pending (6-2-1-3)\"\n\nDEFINE STEP setupFirstPlayer                                              -- §6-2-1-4\n  phase: \"setup\"\n  optional: false\n  prompt: \"chooseFirst\"\n  text: \"by a random method one player is chosen, and that player chooses who goes first (6-2-1-4, 6-2-1-5)\"\n\nDEFINE STEP setupShuffle                                                  -- §6-2-1-7\n  phase: \"setup\"\n  optional: false\n  text: \"each player shuffles their deck and places it face down in their Deck Area (6-2-1-7)\"\n\nDEFINE STEP setupZDeck                                                    -- §6-2-1-8\n  phase: \"setup\"\n  optional: false\n  text: \"each player places their Z-Deck face down in their Z-Deck Area (6-2-1-8)\"\n\nDEFINE STEP setupHand                                                     -- §6-2-1-9\n  phase: \"setup\"\n  optional: false\n  text: \"each player draws 6 cards from their deck as their opening hand (6-2-1-9)\"\n\nDEFINE STEP setupMulligan                                                 -- §6-2-1-9-1\n  phase: \"setup\"\n  optional: true\n  prompt: \"mulligan\"\n  text: \"beginning with the starting player, each player may return their hand to their deck, shuffle, and draw 6 new cards — once (6-2-1-9, 6-2-1-9-1)\"\n\nDEFINE STEP setupLife                                                     -- §6-2-1-10\n  phase: \"setup\"\n  optional: false\n  text: \"each player places the top 8 cards of their deck face down in their Life Area (6-2-1-10)\"\n\nDEFINE STEP setupEnergyMarker                                             -- §6-2-1-11\n  phase: \"setup\"\n  optional: false\n  text: \"the player who goes second places 1 energy marker in their Energy Area, and the player who goes first places none (6-2-1-11)\"\n\nDEFINE STEP setupStart                                                    -- §6-2-1-12\n  phase: \"setup\"\n  optional: false\n  text: \"the first player begins the game and starts their turn (6-2-1-12)\"\n\n-- ── the Charge Phase (§7-2) ───────────────────────────────────────────────\n\nDEFINE STEP chargeTurnEffects                                             -- §7-2-2\n  phase: \"charge\"\n  optional: false\n  text: \"effects that last \\\"for the turn\\\" occur, for the turn player and then for the non-turn player (7-2-2, 7-2-3)\"\n\nDEFINE STEP chargeContinuousEnd                                           -- §7-2-4\n  phase: \"charge\"\n  optional: false\n  always: true\n  text: \"continuous effects that last \\\"until the start of your opponent's turn\\\" end (7-2-4)\"\n\nDEFINE STEP chargePending                                                 -- §7-2-5\n  phase: \"charge\"\n  optional: false\n  text: \"effects that read \\\"at the beginning of the turn\\\" and \\\"at the beginning of the Charge Phase\\\" enter pending (7-2-5)\"\n\nDEFINE STEP chargeActivate                                                -- §7-2-7\n  phase: \"charge\"\n  optional: false\n  text: \"each player switches every card in their Leader, Battle, Energy and Unison Areas that is in Rest Mode to Active Mode (7-2-7)\"\n\nDEFINE STEP chargeDraw                                                    -- §7-2-9\n  phase: \"charge\"\n  optional: false\n  text: \"the turn player draws 1 card, except the player who goes first, on their first turn (7-2-9, 7-2-9-1)\"\n\nDEFINE STEP chargeEnergy                                                  -- §7-2-11\n  phase: \"charge\"\n  optional: true\n  prompt: \"charge\"\n  text: \"the turn player may place 1 card from their hand in their Energy Area (7-2-11)\"\n\n-- ── the Main Phase (§7-3) ─────────────────────────────────────────────────\n\nDEFINE STEP mainPending                                                   -- §7-3-2\n  phase: \"main\"\n  optional: false\n  text: \"effects that read \\\"at the beginning of the Main Phase\\\" enter pending (7-3-2)\"\n\nDEFINE STEP mainActions                                                   -- §7-3-4\n  phase: \"main\"\n  optional: false\n  prompt: \"main\"\n  text: \"the turn player is granted a free timing: play a card, activate an [Activate : Main] skill, grow a Unison Card, attack, or end the Main Phase (7-3-4)\"\n\nDEFINE STEP mainEndPending                                                -- §7-3-5-1-1\n  phase: \"mainEnd\"\n  optional: false\n  text: \"skills that read \\\"at the end of the Main Phase\\\" enter pending (7-3-5-1-1)\"\n\nDEFINE STEP mainEndEffects                                                -- §7-3-5-1-3\n  phase: \"mainEnd\"\n  optional: false\n  text: \"effects that last \\\"for the Main Phase\\\" end, for the turn player and then for the non-turn player (7-3-5-1-3, 7-3-5-1-4)\"\n\n-- ── the End Phase (§7-4) ──────────────────────────────────────────────────\n\nDEFINE STEP endPending                                                    -- §7-4-2\n  phase: \"end\"\n  optional: false\n  text: \"skills that read \\\"at the end of the turn\\\" enter pending, except any [Auto] whose trigger condition was already fulfilled this turn (7-4-2)\"\n\nDEFINE STEP endRepeat                                                     -- §7-4-4\n  phase: \"end\"\n  optional: false\n  LIMIT 5\n  text: \"if an \\\"at the end of the turn\\\" [Auto] has still not been fulfilled this turn, the End Phase is carried out again from the beginning (7-4-4)\"\n\nDEFINE STEP endEffects                                                    -- §7-4-5\n  phase: \"end\"\n  optional: false\n  always: true\n  text: \"every effect that lasts \\\"for the turn\\\" or \\\"until the end of the turn\\\" ends, for the turn player and then for the non-turn player (7-4-5, 7-4-6)\"\n\nDEFINE STEP endTurn                                                       -- §7-4-7\n  phase: \"end\"\n  optional: false\n  always: true\n  text: \"the turn ends, the non-turn player becomes the turn player, and play proceeds to the next turn's Charge Phase (7-4-7)\"\n\n-- ── the game is over (§0-1-3) ─────────────────────────────────────────────\n\nDEFINE STEP gameEnd                                                       -- §0-1-3\n  phase: \"over\"\n  optional: false\n  prompt: \"gameOver\"\n  text: \"a player has fulfilled a defeat condition and the game has ended (0-1-3, 0-1-3-1)\"\n\n-- ── how the game ends (§0-1-3) ────────────────────────────────────────────\n--\n-- The two defeat conditions of 0-1-3-2. A player who fulfils either loses\n-- immediately (0-1-3-1), and a player whose opponent loses while they did not\n-- wins (0-1-3).\n--\n-- Two more ways the manual ends a game are not declared, because a condition\n-- in this language reads the board and neither of these is on it: conceding\n-- (0-1-3-4), which is a player's act and which no card may cause or replace\n-- (0-2-2-1), and a card that makes a player win or lose as its effect\n-- resolves (0-1-3-5). Nor can the draw of 0-1-3-3 be said, since \"both\n-- players fulfil a defeat condition simultaneously\" is a statement about the\n-- other declarations rather than about the board. All three are in the\n-- history entry of 12 Sep 2026.\n\nDEFINE WIN lifeOut                                                        -- §0-1-3-2\n  IF count(IN you.life) <= 0\n  result: lose\n  who: you\n  text: \"there are no cards in your Life Area (0-1-3-2)\"\n\nDEFINE WIN deckOut                                                        -- §0-1-3-2\n  IF count(IN you.deck) <= 0\n  result: lose\n  who: you\n  text: \"there are no cards in your Deck Area (0-1-3-2)\"\n",
  "keywords.rules": "-- Every keyword skill KEYWORD_NAMES (vm/script-schema.ts) lists, in that\n-- order. TAKES is the arity KeywordSkill (types.ts) carries and\n-- keywordOf (text/cards.ts) reads back; scripts/verify/rulesets.ts checks\n-- both against this file. text: is the glossary's meaning line, verbatim\n-- (src/lib/arena/glossary.ts) — /arena/rules/keywords renders it from here\n-- rather than from glossary.ts since #163, and scripts/verify/game-page.ts\n-- holds the two equal so the page and the record cannot quietly disagree.\n--\n-- Nineteen HOOK bodies over eighteen keywords, written by Stage 7's four hook\n-- groups (#154-#157) against the contract #153 built, and [Ultimate]'s\n-- wouldLeave (1 Oct 2026): [Field]'s onEnter,\n-- [Indestructible]'s koByEffect, [Barrier]'s chooseable, [Deflect]'s\n-- counterWindow, [Servant]'s attrBonus and activeStep, [Energy-Exhaust]'s\n-- chargeLimit, [Unique]'s playRefused, [Warrior of Universe 7]'s and\n-- [Invoker]'s altPayment, [Empower]'s markerCarry, [Heroic]/[Villainous]'s\n-- afterSkill,\n-- [Critical]/[Strike]/[Victory Strike]'s beforeDamage and [Revenge]/\n-- [Attack]'s battleEnd. Every other keyword's\n-- own moments are still the engine's, and each one's trailing comment says\n-- which group looked at it and why it is deferred — the header used to say\n-- \"no HOOK bodies yet\", which stopped being true at #154 and was found by\n-- #166's pre-flip review.\n--\n-- Eighteen DO bodies, the whole-keyword activations that are no hook at all\n-- (docs/arena-ruleset-spec.md §4.4): [Overlord], [Evolve], [Union],\n-- [Successor], [Arrival], [Aegis], [Rejuvenate], [Z-Awaken], [Wish],\n-- [Awaken], [Over Realm] and [Swap] are moves (`offer:`),\n-- each offered as an [Activate: Main] — [Arrival] and [Aegis] an [Activate:\n-- Battle], [Wish] and [Awaken] both — line with its own REFUSE and menu\n-- words ([Wish] and [Awaken] with an AFTER as well), and [Offering],\n-- [Z-Stack], [Revive], [Alliance], [Revenge] and [Attack] answer a moment\n-- (`at:`), pended like an [Auto] — [Alliance] running its printed effect\n-- where its DO says (`printedEffect`), the last two with an empty DO,\n-- announced as the legacy engine announces them, their effect a battleEnd\n-- HOOK. 9-1-4 immunity printed as a [Permanent] is no keyword at all and is\n-- read beside the other statics (`vm/effects.ts`, #154). Any other of that\n-- shape still to write says what it is missing in its trailing comment.\n-- [Spirit Boost] needs no body: it is a price (costs.rules' spiritBoost).\n\n-- 22-2\nDEFINE KEYWORD Awaken\n  TAKES (surge: boolean)\n  text: \"A Leader's own skill. Meet the printed condition, pay the cost, carry out the effect, then flip the Leader onto its awakened side. [Awaken: Surge] is the same skill under another name, and card text saying “[Awaken] skills” means both.\"\n  -- #156: [Wish]'s body under its own name (22-2-4 and 22-25-4 are the same\n  -- rule) — a move offered at the Main Phase and at the combo prompt from a\n  -- face-up Leader that prints an awakened side, while the printed condition\n  -- (the record's hoisted price condition) holds; the line's effect runs, and\n  -- `AFTER` flips the Leader once it has, even when the effect stopped to ask\n  -- something. [Awaken: Surge] is the same move: `surge` changes nothing the\n  -- engine does, on either engine, and the menu says \"Awaken\" for both.\n  offer: \"activate:main/battle\"\n  REFUSE zone(area: leader) UNLESS count([self] IN you.leader) >= 1\n  REFUSE other(detail: \"the Leader is already awakened\") UNLESS NOT leaderFlipped()\n  REFUSE other(detail: \"the Leader has no awakened side\") UNLESS leaderMatches(filter: \"card\", back: true)\n  label: \"Awaken: {card} → {back}\"\n  DO {}\n  AFTER {\n    flip(target: [self])\n  }\n\n-- 22-25\nDEFINE KEYWORD Wish\n  TAKES ()\n  text: \"The same shape as [Awaken]: a condition, an effect, and then the Leader is flipped over.\"\n  -- #155: a move, offered at the Main Phase and at the combo prompt from a\n  -- face-up Leader that prints an awakened side, while the printed condition\n  -- holds (the record hoists it into the line's price, 9-1-3). The effect is\n  -- the line's own; the flip is the keyword's, and comes after it (`AFTER`,\n  -- 22-25-4) even when the effect stops to ask something — the legacy engine\n  -- queues it ahead for the same reason. [Awaken] (22-2) is the same body,\n  -- declared by #156.\n  offer: \"activate:main/battle\"\n  REFUSE zone(area: leader) UNLESS count([self] IN you.leader) >= 1\n  REFUSE other(detail: \"the Leader is already awakened\") UNLESS NOT leaderFlipped()\n  REFUSE other(detail: \"the Leader has no awakened side\") UNLESS leaderMatches(filter: \"card\", back: true)\n  label: \"Wish: {card} → {back}\"\n  DO {}\n  AFTER {\n    flip(target: [self])\n  }\n\n-- 22-3\nDEFINE KEYWORD Field\n  TAKES ()\n  text: \"An Extra Card that stays on the table in Active Mode instead of going to the Drop Area. Its other skills work from there, and playing another [Field] Extra drops the one already out.\"\n  -- A move (2 Oct 2026), offered as an [Activate: Main] from the hand\n  -- (22-3-2) — and at [Activate: Battle] timings as well while a [Permanent]\n  -- permits it for this card (`permit(what: fieldBattle)`, BT29-041/-042),\n  -- which `vm/activate.ts`'s `activationsOf` reads as widening the line's\n  -- kind to `activate:main/battle`. The price is the Extra's own energy cost\n  -- (12-2-2, `boundFor`), and the Extra is not put in the Drop as an Extra\n  -- used from the hand otherwise is: the `DO` plays it into the Battle Area in\n  -- Active Mode, and the onEnter hook below drops the [Field] Extra already\n  -- out (22-3-5). One difference from the legacy engine, recorded: the label\n  -- does not add the cost in brackets.\n  offer: \"activate:main\"\n  REFUSE zone(area: hand) UNLESS count([self] IN you.hand) >= 1\n  label: \"Field: place {card}\"\n  DO {\n    play(target: [self])\n  }\n  HOOK onEnter {\n    choose(sel: UP TO 1 \"Extra Card with [Field]\" IN you.battle otherThanSelf, as: \"t\")\n    moveTo(target: $t, to: drop)\n  }\n\n-- 22-4\nDEFINE KEYWORD Blocker\n  TAKES ()\n  text: \"When one of your other cards is attacked, switch this card to Rest Mode to become the guard card instead.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-6\nDEFINE KEYWORD Critical\n  TAKES ()\n  text: \"Life damage this card deals by attacking goes to the opponent's Drop Area instead of their hand.\"\n  -- #156: read as the attacker's damage lands (`beforeDamage`, a query hook\n  -- so it changes this damage rather than a later one): the life cards go\n  -- to the Drop face up, and \"when your life is placed in your Drop\" hears\n  -- the move. Battle damage only, as on the legacy engine.\n  HOOK beforeDamage {\n    battleDamage(to: drop)\n  }\n\n-- 22-7\nDEFINE KEYWORD Strike\n  TAKES (x: number)\n  text: \"When this card would deal less than X life damage by attacking, it deals X instead — 2, 3 or 4.\"\n  -- #156: the same hook as [Critical]: X life damage to a Leader, and X\n  -- markers off a Unison guard (13-5-2-2), as on the legacy engine.\n  HOOK beforeDamage {\n    battleDamage(atLeast: $x)\n  }\n\n-- 22-8\nDEFINE KEYWORD Attack\n  TAKES (x: number)\n  text: \"When this card attacks, it switches back to Active Mode at the end of the battle — X−1 times a turn.\"\n  -- #156: two halves, as the legacy engine has them. The line answers\n  -- `attacks` (`at:`), so it is announced as the card attacks, as the legacy\n  -- `keywordTriggers` case is. The stand is the `battleEnd` hook, run on the\n  -- attacker at the Battle End Step after a guard's [Revenge]: while the card\n  -- is still in play and has declared fewer than X attacks this turn — the\n  -- one ending included — it switches to Active Mode (22-8-3). The legacy\n  -- engine counts the stands granted (`extraAttacks`); this counts the\n  -- attacks (`attacked`), which is the same number on a card that has\n  -- attacked only with the keyword.\n  at: [attacks]\n  DO {}\n  HOOK battleEnd {\n    if(cond: all([inBattle(sel: [self], role: attacker), any([count([self] IN you.battle) >= 1, count([self] IN you.leader) >= 1]), NOT attacked(sel: [self], atLeast: $x)]), then: {\n      switchMode(target: [self], mode: active)\n    })\n  }\n\n-- 22-9\nDEFINE KEYWORD Revenge\n  TAKES ()\n  text: \"When this card becomes the guard card, KO the attacking card at the end of the battle.\"\n  -- #156: two halves, as the legacy engine has them. The line answers\n  -- `attacked` (`at:`), so it pends and is announced as the card becomes the\n  -- guard — when it is attacked, or when it blocks — exactly as the legacy\n  -- `keywordTriggers` case is; its `DO` has nothing of its own to do. The KO\n  -- is the contract's own worked example, `HOOK battleEnd`, which\n  -- `vm/battle.ts`'s Battle End Step fires on both cards of the fight — the\n  -- body acts only on the one that is the guard then — after the combo cards\n  -- have gone to the Drop and before\n  -- `state.battle` clears — the legacy `battleCleanup` order. A Battle Card\n  -- attacker only, as there (a Leader is not KO'd by it). The Revenge card\n  -- need not survive the fight: a card KO'd by the battle still answers.\n  at: [attacked]\n  DO {}\n  HOOK battleEnd {\n    if(cond: all([inBattle(sel: [self], role: guard), count([attacker] IN opponent.battle) >= 1]), then: {\n      ko(target: [attacker])\n    })\n  }\n\n-- 22-12\nDEFINE KEYWORD Indestructible\n  TAKES ()\n  text: \"This card can't be KO'd or moved out of your Battle Area by the opponent's skills or as a result of battle.\"\n  -- #154: the \"as a result of battle\" half is read directly in\n  -- `vm/battle.ts`'s `damageWork`, not through this hook — a battle's own KO\n  -- is not an effect's. A skill's KO is real since #146 (`vm/host.ts`), and\n  -- the shared interpreter's `ko` case skips an opponent's [Indestructible]\n  -- card itself, before this hook is asked — see docs/arena-ruleset-spec.md §4.3.\n  HOOK koByEffect {\n    forbid(what: beKOdBySkill, side: opponent, until: game)\n    forbid(what: beMovedBySkill, side: opponent, until: game)\n  }\n\n-- 22-16\nDEFINE KEYWORD Barrier\n  TAKES ()\n  text: \"This card can't be chosen by the skills of cards your opponent masters.\"\n  HOOK chooseable {\n    forbid(what: beChosen, side: opponent, until: game)\n  }\n\n-- 22-20\nDEFINE KEYWORD Deflect\n  TAKES ()\n  text: \"This card isn't affected by your opponent's [Counter: Play] skills. Valid in every area.\"\n  -- #150: asked of the card being played when its [Counter: Play] window\n  -- opens (`vm/battle.ts`'s `windowClosedBy`), read declaratively like every\n  -- query hook — a forbid on activating a counter empties the window, the\n  -- legacy `counterCandidates`' own first line.\n  HOOK counterWindow {\n    forbid(what: activateCounter, side: opponent, until: game)\n  }\n\n-- 22-39\nDEFINE KEYWORD Unique\n  TAKES ()\n  text: \"While a card with [Unique] is in play you can't play another card with the same name. If two are somehow in play at once, their master keeps one and drops the rest.\"\n  -- #157: asked of every card in play when a play is checked\n  -- (`vm/program.ts`'s `forbiddenBy`) — the rule is the in-play card's, and it\n  -- refuses its master's declared play of a card with its name, as the legacy\n  -- `canPlay`/`whyNotPlay` do; a play a skill makes is not refused here, as it\n  -- is not there. 21-11's half — two in play at once, the master keeps one —\n  -- is rule processing, which the rules engine does not run yet.\n  HOOK playRefused {\n    forbid(what: play, side: you, sameNameAsSelf: true, bySkill: false, until: game)\n  }\n\n-- 22-40\nDEFINE KEYWORD Servant\n  TAKES ()\n  text: \"+10000 power, and the card does not switch to Active Mode during its master's Charge Phase.\"\n  -- #154 (hook group A) builds the power half (attrBonus); #155 (hook\n  -- group B) the Charge Phase half (activeStep).\n  HOOK attrBonus {\n    modifyAttr(target: [self], attr: power, amount: 10000)\n  }\n  HOOK activeStep {\n    forbid(what: switchToActive, until: game)\n  }\n\n-- 22-31\nDEFINE KEYWORD \"Energy-Exhaust\"\n  TAKES ()\n  text: \"When this card is placed in an Energy Area, it arrives in Rest Mode. Valid in every area.\"\n  HOOK chargeLimit {\n    modifyAttr(target: [self], attr: mode, mode: rest)\n  }\n\n-- 22-18\nDEFINE KEYWORD \"Victory Strike\"\n  TAKES ()\n  text: \"Deal life damage by attacking with this card and you win the game.\"\n  -- #156: the same hook: once its life damage has landed (and its moments\n  -- fired) the game ends in its master's favour (22-18-2), and against a\n  -- Unison guard it takes every marker (13-5-2-2), as on the legacy engine.\n  HOOK beforeDamage {\n    battleDamage(allMarkers: true, wins: true)\n  }\n\n-- 22-19\nDEFINE KEYWORD \"Warrior of Universe 7\"\n  TAKES ()\n  text: \"Treat your ≪Universe 7≫ cards in every area as having no specified cost — the coloured part of a play's price.\"\n  -- #154: an `altPayment` body, read as a standing change the way a\n  -- [Permanent]'s program is (`vm/program.ts`'s statics): while the card is\n  -- your Leader or in your Battle Area — the legacy `playCost`'s two places —\n  -- your ≪Universe 7≫ cards where a price is asked, the hand and the Z-Deck,\n  -- have no specified cost, after every other change to it (22-19-2). The\n  -- total is untouched. The trait is matched as a trait, where the legacy\n  -- engine looks for \"universe 7\" anywhere in one.\n  HOOK altPayment {\n    if(cond: any([count([self] IN you.leader) >= 1, count([self] IN you.battle) >= 1]), then: {\n      costReduction(target: \"≪Universe 7≫ card\" IN you.hand|zDeck, amount: 0, what: specified, all: true)\n    })\n  }\n\n-- 22-14\nDEFINE KEYWORD Ultimate\n  TAKES ()\n  text: \"A deck may hold at most one card with [Ultimate], and a card with it that leaves play is removed from the game rather than going anywhere else.\"\n  -- 22-14-3 is a replacement (9-10): the card leaving play or a Combo Area\n  -- for anywhere but another of those goes to `removed` *instead* — one move,\n  -- and the moments of that move. Owner's decision of 1 Oct 2026: it rides on\n  -- the 9-10 replacements (`vm/replace.ts`), not on an `onLeave` query. The\n  -- `wouldLeave` hook is read before the card goes anywhere, its leaf the\n  -- same `replace` record a [Permanent] prints, applied after any\n  -- [Permanent]'s replacement as the card's own rule — the legacy `move`\n  -- folds it into 14-1-4's Z-card line. The cards under it are not\n  -- redirected. The deck limit is `legality`'s, on both engines.\n  HOOK wouldLeave {\n    replace(event: leave, with: {\n      moveTo(target: [self], to: removed)\n    })\n  }\n\n-- 22-17\nDEFINE KEYWORD \"Super Combo\"\n  TAKES ()\n  text: \"A deck may hold at most four cards with [Super Combo], counted across all of them.\"\n  -- Stage 7 (#153–#157)\n\n-- 22-28\nDEFINE KEYWORD \"Dragon Ball\"\n  TAKES ()\n  text: \"As many copies of a [Dragon Ball] card as you like, as long as no more than seven [Dragon Ball] cards are in the deck all told.\"\n  -- #155: no body to write — a deck-building rule (`legality`), which no game\n  -- reads on either engine.\n\n-- 22-24\nDEFINE KEYWORD Wormhole\n  TAKES ()\n  text: \"[Over Realm] and [Dark Over Realm] may be activated twice a turn between them instead of once.\"\n  -- #157: no body of its own. Its only effect is [Over Realm]'s limit, and\n  -- that keyword's `REFUSE oncePerTurn` reads it — a second use is allowed\n  -- while a card with [Wormhole] is in your Leader, Battle or Unison Area\n  -- (`count(\"card with [Wormhole]\" IN you.play)`), as on the legacy engine.\n\n-- 22-37\nDEFINE KEYWORD Invoker\n  TAKES ()\n  text: \"A Red/Blue multicolour Extra Card in your hand may be activated by switching one active Red/Blue multicolour energy to Rest Mode instead of paying its energy cost.\"\n  -- #155: an `altPayment` body, read as a standing change the way [Warrior\n  -- of Universe 7]'s is, off the card while it is in play (the legacy\n  -- `cardsInPlay`): your Red/Blue multicolour Extra Cards in the hand may be\n  -- played — which is how an Extra is used from there (4-2), so `DEFINE\n  -- ACTION activate` says `alt: \"play\"` — for one energy that only an active\n  -- Red/Blue multicolour card in your Energy Area may pay, rested where it\n  -- stands (`rest`). The line's own orbs are still paid, out of what is left.\n  HOOK altPayment {\n    altCost(target: (type = EXTRA AND colors = [Red, Blue] AND multiColor = true AND notColors = [Green, Yellow, Black, White, Colorless]) IN you.hand, pay: energy, orbs: [any], for: play, rest: (colors = [Red, Blue] AND multiColor = true AND notColors = [Green, Yellow, Black, White, Colorless]) IN you.energy active)\n  }\n\n-- 22-35\nDEFINE KEYWORD Heroic\n  TAKES ()\n  text: \"When you play another card with [Heroic], draw 1 card; the skill is then negated on this card for the rest of the turn.\"\n  -- The \"negated on this card for the rest of the turn\" half is not built: a\n  -- hook body's frame carries no skillIndex for `negate(what: own)` to read\n  -- (`vm/program.ts`'s `hookFrame`), so this fires once per other [Heroic]\n  -- card played in the turn rather than once. Named, not guessed around.\n  HOOK afterSkill {\n    if(cond: count(\"card with [Heroic]\" FROM $source) >= 1, then: {\n      draw(n: 1)\n    })\n  }\n\n-- 22-36\nDEFINE KEYWORD Villainous\n  TAKES ()\n  text: \"When you play another card with [Villainous], your opponent chooses a card in their hand and drops it; the skill is then negated for the rest of the turn.\"\n  -- Same gap as [Heroic]'s own HOOK: fires every time, not once a turn.\n  HOOK afterSkill {\n    if(cond: count(\"card with [Villainous]\" FROM $source) >= 1, then: {\n      choose(sel: 1 IN opponent.hand, chooser: opponent, as: \"t\")\n      moveTo(target: $t, to: drop)\n    })\n  }\n\n-- 22-33\nDEFINE KEYWORD Offering\n  TAKES ()\n  text: \"When this Battle Card is played, your opponent may put one of their life cards in their Drop Area. If they don't, you draw 2 cards.\"\n  -- A whole-keyword activation that answers a moment (`at:`): the line pends\n  -- at `played` as an [Auto] whose record said so would, and its `DO` runs as\n  -- it resolves. The question is the opponent's, worded as the legacy\n  -- engine's own `offering` prompt words its two answers, and the life card\n  -- that goes is the top one, as it is there; with no life left there is\n  -- nothing to ask and the draw simply happens (the legacy engine's own\n  -- shortcut). One difference, recorded rather than matched: the question\n  -- is the general `chooseMode` prompt here, not a prompt kind of its own.\n  at: [played]\n  DO {\n    if(cond: count(IN opponent.life) >= 1, then: {\n      chooseMode(modes: [\"Drop 1 life (deny the draw)\" {\n        moveTo(target: TOP 1 IN opponent.life, to: drop, reveal: true)\n      }, \"Keep life (opponent draws 2)\" {\n        draw(n: 2)\n      }], reason: \"[Offering]: drop 1 life, or your opponent draws 2\", chooser: opponent)\n    }, else: {\n      draw(n: 2)\n    })\n  }\n\n-- 22-5\nDEFINE KEYWORD Evolve\n  TAKES (variant: string)\n  text: \"From hand: pay the cost, choose one of your Battle Cards matching the printed description, and play this card on top of it. [Xeno-Evolve] sends the chosen card to the Warp instead of stacking onto it.\"\n  -- A move (#157), offered as an [Activate: Main] used from the hand (22-5-2)\n  -- while a Battle Card matching the printed description is out — `asPrinted`\n  -- reads \"<V1>\" off the line, the legacy `parseFilter(sk.effect || sk.cost)`.\n  -- The price is the line's printed orbs. \"when you use this card's [Evolve]\n  -- from your hand\" is the move's `keywordActivated(from: hand)`. The stack\n  -- keeps the host's place, mode and power effects (`play … onto`,\n  -- `vm/play.ts`'s `stackOnto`). [Xeno-Evolve] sends the host to the Warp and\n  -- plays this card beside where it was (22-5-6). A base named with the\n  -- activation (`onto`, offered where a price change is scoped to that base —\n  -- EX03-16, `vm/activate.ts`'s `evolveOntoBases`) arrives already bound as\n  -- `$base`, and is not asked for again.\n  offer: \"activate:main\"\n  REFUSE zone(area: hand) UNLESS count([self] IN you.hand) >= 1\n  REFUSE target(reason: \"no {line} in your Battle Area\") UNLESS count(IN you.battle asPrinted) >= 1\n  label: \"{variant} {card} onto a {line}\"\n  DO {\n    if(cond: count(FROM $base) <= 0, then: {\n      choose(sel: 1 IN you.battle asPrinted, as: \"base\", reason: \"[Evolve]: choose the card to evolve\")\n    })\n    if(cond: oneOf(value: $variant, of: [\"Xeno-Evolve\"]), then: {\n      moveTo(target: $base, to: warp)\n      play(target: [self])\n    }, else: {\n      play(target: [self], onto: $base)\n    })\n  }\n\n-- 22-13\nDEFINE KEYWORD Union\n  TAKES (variant: string)\n  text: \"Three ways to play a Battle Card by naming characters. Fusion drops one of each named character from your hand, both of equal power. Potara plays this card on top of two named characters in your Battle Area. Absorb is activated from the Battle Area, and its text says which card is played onto this one.\"\n  -- A move (#157), one declaration for its three variants, told apart by\n  -- `oneOf(value: $variant, …)`. Fusion and Potara are used from the hand and\n  -- need each character the line names in ‹…› on a different card\n  -- (`eachNamed`) — in the hand, of one power, for Fusion (22-13-4); in the\n  -- Battle Area for Potara (22-13-5). Absorb is used from the Battle Area\n  -- (22-13-6-2) and its `DO` does nothing of its own: the line's printed\n  -- effect, which runs after the `DO` of every keyword move, is what says\n  -- which card is played onto this one. \"when you activate a [Union] skill\"\n  -- and \"when this card's [Union-Absorb] is activated\" are the move's\n  -- `keywordActivated` under both names.\n  offer: \"activate:main\"\n  REFUSE zone(area: battle) UNLESS any([NOT oneOf(value: $variant, of: [\"Absorb\"]), count([self] IN you.battle) >= 1])\n  REFUSE zone(area: hand) UNLESS any([oneOf(value: $variant, of: [\"Absorb\"]), count([self] IN you.hand) >= 1])\n  REFUSE target(reason: \"needs {names} in hand\") UNLESS any([NOT oneOf(value: $variant, of: [\"Fusion\"]), eachNamed(sel: IN you.hand otherThanSelf)])\n  REFUSE target(reason: \"the two cards must have equal power\") UNLESS any([NOT oneOf(value: $variant, of: [\"Fusion\"]), eachNamed(sel: IN you.hand otherThanSelf, samePower: true)])\n  REFUSE target(reason: \"needs {names} in your Battle Area\") UNLESS any([NOT oneOf(value: $variant, of: [\"Potara\"]), eachNamed(sel: IN you.battle)])\n  label: \"Union-{variant} {card}\"\n  DO {\n    if(cond: oneOf(value: $variant, of: [\"Fusion\"]), then: {\n      choose(sel: 2 IN you.hand otherThanSelf asPrinted, as: \"pair\", reason: \"[Union-Fusion]: choose the named cards to drop\")\n      moveTo(target: $pair, to: drop, cause: cost)\n      play(target: [self])\n    })\n    if(cond: oneOf(value: $variant, of: [\"Potara\"]), then: {\n      choose(sel: 1 IN you.battle asPrinted, as: \"first\", reason: \"[Union-Potara]: choose the card to play this one onto\")\n      play(target: [self], onto: $first)\n      choose(sel: 1 IN you.battle otherThanSelf asPrinted, as: \"second\", reason: \"[Union-Potara]: choose the card to put under it\")\n      moveTo(target: $second, to: under, under: [self])\n    })\n  }\n\n-- 22-15, 22-23\nDEFINE KEYWORD \"Over Realm\"\n  TAKES (x: number, dark: boolean)\n  text: \"With X or more cards in your Drop Area — X or more black cards, for the dark one — send your whole Drop Area to the Warp as the cost and play this card from hand. The two share one activation a turn. A card played with [Over Realm] goes to the Warp at the end of that turn.\"\n  -- A move (#157), offered as an [Activate: Main] from the hand, as the\n  -- legacy `activatable` case gates it: the two variants share one use a\n  -- turn, two while a card with [Wormhole] is in play (22-24) — a counted\n  -- player fact (`overRealms`, attributes.rules) — and want X or more cards\n  -- in the Drop, black ones for the dark variant (`flag(value: $dark)`).\n  -- The price is the line's printed orbs. Taken, the use is counted, the\n  -- whole Drop goes to the Warp as the cost, the card is scheduled back to\n  -- the Warp as the turn ends (for the dark variant too, which 22-23 does not\n  -- ask for — the legacy engine's approximation, kept so the two agree), and\n  -- it is played through the [Counter: Play] window. \"when you play a card\n  -- using [Over Realm]\" is the move's `keywordActivated`; \"when this card is\n  -- played using [Over Realm]\" is the play's own `moved`, which `using:` marks\n  -- as this keyword's (`playedUsingOverRealm`). One difference,\n  -- recorded: the refusal for too few cards does not add \"(N there)\".\n  -- From the Warp as well (owner-approved 2 Oct 2026) while the card's own\n  -- [Permanent] says \"This card's [Over Realm] skill can be activated from\n  -- its owner's Warp under the same conditions as if it were in your hand\"\n  -- (BT31-150): a `permit` of `overRealmFromWarp`, read in the Warp. The\n  -- `activate` action's FOR names the Warp, and `vm/activate.ts`'s\n  -- `activationsOf` offers no line there but this one, and this one only\n  -- under that permission — so the zone gate below may accept the Warp, and\n  -- every other gate (the count, the shared limit, the whole-Drop cost, the\n  -- return to the Warp as the turn ends) is the hand's, unchanged.\n  offer: \"activate:main\"\n  REFUSE zone(area: hand) UNLESS any([count([self] IN you.hand) >= 1, count([self] IN you.warp) >= 1])\n  REFUSE oncePerTurn(what: \"Over Realm\") UNLESS any([NOT playerAttr(name: \"overRealms\", atLeast: 1), all([count(\"card with [Wormhole]\" IN you.play) >= 1, NOT playerAttr(name: \"overRealms\", atLeast: 2)])])\n  REFUSE condition(text: \"{x} or more {dark?black }cards in your Drop Area\") UNLESS any([all([NOT flag(value: $dark), count(IN you.drop) >= $x]), all([flag(value: $dark), count((colors = [Black]) IN you.drop) >= $x])])\n  label: \"{dark?Dark }Over Realm {x}: play {card} (Drop → Warp)\"\n  DO {\n    setPlayerAttr(name: \"overRealms\", add: 1)\n    moveTo(target: IN you.drop, to: warp, cause: cost)\n    delay(at: turnCleanup, ops: {\n      moveTo(target: [self] IN you.battle, to: warp)\n    }, label: \"back to the Warp as the turn ends\")\n    play(target: [self], counterWindow: true, using: \"Over Realm\")\n  }\n\n-- 22-22\nDEFINE KEYWORD Swap\n  TAKES (x: number)\n  text: \"Return this Battle Card to your hand and play a named Battle Card with an energy cost of X from your hand in its place.\"\n  -- A move (#157), offered as an [Activate: Main] from the Battle Area while\n  -- a Battle Card with an energy cost of X is in the hand (22-22-3: with\n  -- none to choose it cannot be activated). The choice is filtered by cost\n  -- only, as on the legacy engine — a [Swap] that names a character offers\n  -- every cost-X Battle Card. The price is the line's printed orbs; the card\n  -- returns to the hand as the cost whether or not one is chosen, and the\n  -- chosen card is played through the [Counter: Play] window.\n  offer: \"activate:main\"\n  REFUSE zone(area: battle) UNLESS count([self] IN you.battle) >= 1\n  REFUSE target(reason: \"no cost-{x} Battle Card in your hand\") UNLESS count((type = BATTLE AND costMin = $x AND costMax = $x) IN you.hand) >= 1\n  label: \"Swap {card} for a cost-{x} card from hand\"\n  DO {\n    choose(sel: UP TO 1 (type = BATTLE AND costMin = $x AND costMax = $x) IN you.hand, as: \"swapIn\", reason: \"[Swap]: the Battle Card to play in its place, or none\")\n    moveTo(target: [self], to: hand, cause: cost)\n    play(target: $swapIn, counterWindow: true)\n  }\n\n-- 22-29\nDEFINE KEYWORD Arrival\n  TAKES (colors: colors)\n  text: \"During a battle, when the original colours of the Battle Cards in your Combo Area cover every colour named, pay the cost and play this card from hand.\"\n  -- #155: a move, offered as an [Activate: Battle] at the combo prompt\n  -- (22-29-4) from the hand, once the cards in your Combo Area carry every\n  -- colour it names between them (`covers`, 22-29-3). The price is the line's\n  -- printed orbs; the effect is the play itself (22-29-5), through the\n  -- [Counter: Play] window a declared play opens, as on the legacy engine.\n  offer: \"activate:battle\"\n  REFUSE zone(area: hand) UNLESS count([self] IN you.hand) >= 1\n  REFUSE condition(text: \"{colors:and} Battle Cards in your Combo Area\") UNLESS covers(sel: IN you.combo, colors: $colors)\n  label: \"Arrival {colors}: play {card}\"\n  DO {\n    play(target: [self], counterWindow: true)\n  }\n\n-- 22-30\nDEFINE KEYWORD Aegis\n  TAKES (colors: colors)\n  text: \"In the Defense Step of your opponent's turn, drop cards from your hand covering the named colours to switch up to two of your energy from Rest to Active Mode.\"\n  -- #154: a move, offered as an [Activate: Battle] at the combo prompt — so\n  -- only in a battle, and the one the non-turn player is asked is the\n  -- Defense Step's (22-30-4) — from a card in play, while the hand can cover\n  -- the colours (`covers`), for the line's printed orbs, as the legacy\n  -- `activatable` case gates it. Paying first, then up to two cards of the\n  -- colours one at a time (the legacy prompt's `max` is the colours named,\n  -- and every [Aegis] names two); cards that cover them go to the Drop as the\n  -- cost (22-30-3), then up to two rested energy stand (22-30-5) and the\n  -- combo prompt is put again. Picked wrongly, the orbs are spent and nothing\n  -- happens, as there.\n  offer: \"activate:battle\"\n  REFUSE timing(window: defense) UNLESS all([isTurnPlayer(who: opponent), asking(prompt: combo)])\n  REFUSE zone(area: battle) UNLESS count([self] IN you.play) >= 1\n  REFUSE condition(text: \"{colors:and} cards in your hand to drop\") UNLESS covers(sel: IN you.hand, colors: $colors)\n  label: \"Aegis {colors}: drop {colors:and} from hand, stand up to 2 energy\"\n  DO {\n    choose(sel: UP TO 2 (colors = $colors) IN you.hand, as: \"cost\", reason: \"[Aegis]: drop cards covering the named colours from your hand\")\n    if(cond: covers(sel: FROM $cost, colors: $colors), then: {\n      moveTo(target: $cost, to: drop, cause: cost)\n      choose(sel: UP TO 2 IN you.energy rest, as: \"stood\", reason: \"[Aegis]: energy to switch to Active Mode\")\n      switchMode(target: $stood, mode: active)\n    }, else: {\n      note(text: \"Aegis: the cards dropped did not cover the colours, so nothing happened\")\n    })\n  }\n\n-- 22-32\nDEFINE KEYWORD Alliance\n  TAKES (colors: colors)\n  text: \"When this card attacks, you may switch one or more of your other Battle Cards of the named colours to Rest Mode as the cost of the printed effect.\"\n  -- #154: a moment (`at:`), pended and announced as the card attacks, like\n  -- the legacy `keywordTriggers` case; a condition printed before the colon\n  -- is asked before anyone is asked anything. While the card is the\n  -- attacker, its owner picks any number of their other active Battle Cards\n  -- of the named colours, or none (22-32-3); those are rested as the cost,\n  -- and only then is the printed effect announced and run, with the rested\n  -- cards bound as `rested` — \"the total power of the cards switched to Rest\n  -- Mode by this skill\" reads them (`printedEffect`). Declined, nothing\n  -- happens. Each rested card answers \"when this card is switched to Rest\n  -- Mode by an [Alliance] skill\" and not \"…by one of your skills\", as on the\n  -- legacy engine: the switch names the keyword (`by: Alliance`, #157).\n  at: [attacks]\n  DO {\n    if(cond: inBattle(sel: [self], role: attacker), then: {\n      choose(sel: UP TO 99 (colors = $colors) IN you.battle active otherThanSelf, as: \"rested\", reason: \"[Alliance]: Battle Cards to switch to Rest Mode, or none\")\n      if(cond: count(FROM $rested) >= 1, then: {\n        switchMode(target: $rested, mode: rest, by: Alliance)\n        printedEffect()\n      })\n    })\n  }\n\n-- 22-34\nDEFINE KEYWORD Revive\n  TAKES (colors: colors)\n  text: \"When this Battle Card is KO'd, drop cards from hand whose original colours cover both named colours to play it back from your Drop Area. [Revive] is then negated on it for the turn.\"\n  -- #155: a moment (`at:`), pended as the card is KO'd, like the legacy\n  -- `keywordTriggers` case. Asked only while the card is still in the Drop\n  -- and the hand can cover both colours (`covers`); the owner picks up to two\n  -- cards of those colours (`colors = $colors`) or none (22-34-3). Cards that\n  -- cover both go to the Drop as the cost, and the card is played back\n  -- through the [Counter: Play] window (22-34-4). The legacy engine remembers\n  -- the revival for the rest of the turn; here [Revive] is negated on the\n  -- card for the turn, as 22-34-4 says, so a second KO that turn pends\n  -- nothing — where the legacy engine announces the skill and does nothing.\n  at: [koed]\n  DO {\n    if(cond: all([count([self] IN you.drop) >= 1, covers(sel: IN you.hand, colors: $colors)]), then: {\n      choose(sel: UP TO 2 (colors = $colors) IN you.hand, as: \"cost\", reason: \"[Revive]: drop cards covering both colours to play this card back, or none\")\n      if(cond: count(FROM $cost) >= 1, then: {\n        if(cond: all([covers(sel: FROM $cost, colors: $colors), count([self] IN you.drop) >= 1]), then: {\n          moveTo(target: $cost, to: drop, cause: cost)\n          negateOwnSkill(until: turn)\n          play(target: [self], counterWindow: true)\n        }, else: {\n          note(text: \"Revive: the cards chosen did not cover the colours, so it stays in the Drop\")\n        })\n      })\n    })\n  }\n\n-- 22-38\nDEFINE KEYWORD Successor\n  TAKES ()\n  text: \"Drop any number of mono-green, mono-yellow or Green/Yellow Battle Cards from your Battle Area whose energy costs add up to exactly this card's printed cost, and play it from hand.\"\n  -- #155: a move, offered as an [Activate: Main] from the hand while the\n  -- green/yellow cards in your Battle Area can make the card's energy cost\n  -- exactly (`sumsTo`, 22-38-2). The cards are picked one at a time, and only\n  -- those that still leave a way to the exact sum are offered (`choose …\n  -- sumTo`, the legacy `successorAsk`); they go to the Drop as the cost and\n  -- the card is played through the [Counter: Play] window (22-38-3/4). The\n  -- price is the line's printed orbs.\n  offer: \"activate:main\"\n  REFUSE zone(area: hand) UNLESS count([self] IN you.hand) >= 1\n  REFUSE target(reason: \"no green/yellow Battle Cards adding up to its energy cost\") UNLESS sumsTo(sel: (colors = [Green, Yellow] AND notColors = [Red, Blue, Black, White, Colorless]) IN you.battle, attr: energyCost, total: attr([self], energyCost))\n  label: \"Successor: play {card} by dropping green/yellow Battle Cards\"\n  DO {\n    choose(sel: (colors = [Green, Yellow] AND notColors = [Red, Blue, Black, White, Colorless]) IN you.battle, as: \"paid\", reason: \"[Successor]: green/yellow Battle Cards to drop\", sumTo: attr([self], energyCost))\n    if(cond: count(FROM $paid) >= 1, then: {\n      moveTo(target: $paid, to: drop, cause: cost)\n      play(target: [self], counterWindow: true)\n    })\n  }\n\n-- 22-41\nDEFINE KEYWORD Overlord\n  TAKES ()\n  text: \"Put one of your Battle Cards with [Servant] at the bottom of your deck as the cost, and draw 1 card.\"\n  -- A whole-keyword activation that is a move (`offer:`): the line is an\n  -- [Activate: Main] in every sense the `activate` paragraph's gates read\n  -- (negation, 20-14, the window), plus the one requirement 22-41-2 adds.\n  -- The card that pays is chosen; with one [Servant] in play that choice is\n  -- forced and taken without a question, and with several the player picks —\n  -- 22-41-2 says \"one of your Battle Cards\", where the legacy engine takes\n  -- the first. \"when you activate an [Overlord] skill\" is the move's\n  -- `keywordActivated` moment (`triggers.rules`' `overlordActivated`).\n  offer: \"activate:main\"\n  REFUSE target(reason: \"no [Servant] in your Battle Area\") UNLESS count(\"card with [Servant]\" IN you.battle) >= 1\n  REFUSE zone(area: battle) UNLESS count([self] IN you.battle) >= 1\n  label: \"Overlord: return a Servant to the deck, draw 1\"\n  DO {\n    choose(sel: 1 \"card with [Servant]\" IN you.battle, as: \"servant\", reason: \"[Overlord]: the [Servant] to put at the bottom of your deck\")\n    moveTo(target: $servant, to: deck, position: bottom, cause: cost)\n    draw(n: 1)\n  }\n\n-- 22-42\nDEFINE KEYWORD Rejuvenate\n  TAKES (markers: number, lifeAtMost: number)\n  text: \"A Unison Card with cards beneath it: drop one of them and pay the skill cost, then add the top card of your deck to your life.\"\n  -- #155: a move, offered at the Main Phase from the Unison Area while a card\n  -- is beneath it. 22-42-2 prints the skill cost after the tag, so the card\n  -- parser carries its two numbers as the keyword's parameters: `markers`\n  -- (\"Remove N markers from this card\") and `lifeAtMost` (\"if your life is at\n  -- N or less\", left out when the line prints none, and the gate then asks\n  -- nothing). The gates are 13-4's, in the legacy order: enough markers, and\n  -- one marker skill a turn — a move refused by `markerSkillUsed` on its own\n  -- card is a marker skill, so using it spends the lock. The order is the\n  -- legacy one too: DO drops the topmost card from beneath (the legacy\n  -- engine's stated approximation of the master's pick, kept), the line's\n  -- printed effect removes the markers, and AFTER adds the life (22-42-4).\n  offer: \"activate:main\"\n  REFUSE zone(area: unison) UNLESS count([self] IN you.unison) >= 1\n  REFUSE other(detail: \"no card under it to drop\") UNLESS count(UNDER ([self]) IN under) >= 1\n  REFUSE other(detail: \"needs {markers} markers\") UNLESS markers(sel: [self], atLeast: $markers)\n  REFUSE oncePerTurn(what: \"marker skill\") UNLESS NOT markerSkillUsed(sel: [self])\n  REFUSE condition(text: \"your life is at {lifeAtMost} or less\") UNLESS life(side: you, atMost: $lifeAtMost)\n  label: \"Rejuvenate: {markers} markers and a card from under {card} → +1 life\"\n  DO {\n    moveTo(target: UNDER ([self]) TOP 1 IN under, to: drop, cause: cost)\n  }\n  AFTER {\n    moveTo(target: TOP 1 IN you.deck, to: life)\n  }\n\n-- 22-43\nDEFINE KEYWORD \"Spirit Boost\"\n  TAKES (x: number)\n  text: \"Part of a skill's cost: remove X markers from your Unison Card. A skill whose [Spirit Boost] can't be paid can't be activated.\"\n  -- #157: no body — a price, not a move or a hook. `DEFINE COST spiritBoost`\n  -- (costs.rules) is what paying it does, and the `activate` paragraph's COST\n  -- names it; the activation binds X off the line's tag.\n\n-- 22-45\nDEFINE KEYWORD Empower\n  TAKES (color: color, x: number)\n  text: \"When you play this Unison Card over one whose colour matches, you may move up to Y markers from the Unison being replaced onto this one. An [Empower] naming no colour takes them from a Unison of any colour.\"\n  -- #157: a `markerCarry` HOOK, read as the Unison is played over another.\n  -- Its leaf says how many may come across and from a Unison of which\n  -- colour (any, for an [Empower] naming none); the master is asked how\n  -- many, from none to the least of that and what the old one has, before\n  -- it leaves (owner's ruling 9 Sep 2026, \"asked, not assumed\"), and the\n  -- carried markers land after the paid ones, naming the card they left —\n  -- the legacy `empowerCarry` prompt and beats.\n  HOOK markerCarry {\n    carryMarkers(upTo: $x, color: $color)\n  }\n\n-- 22-46\nDEFINE KEYWORD \"Z-Awaken\"\n  TAKES ()\n  text: \"From the Z-Deck, once a turn: pay the Z-Energy cost and the skill cost and place this Z-Leader on top of your already-awakened Leader, which has to match the printed description. The stack is one card from then on.\"\n  -- #155: a move, offered at the Main Phase (the legacy window; 22-46-1 also\n  -- allows a battle) from the Z-Deck, where `DEFINE ACTION activate` reads a\n  -- keyword's own move and nothing else, and paying the card's Z-Energy cost\n  -- after the line's orbs (the activation's `zEnergy` price, bound only from\n  -- the Z-Deck). Refused unless the Leader is awakened and no Z-card yet, and\n  -- matches the description the line prints (`asPrinted`). DO plays the card\n  -- onto the Leader: it takes the Leader Area, the old Leader and its pile go\n  -- under it, power effects and a battle role carry over (22-46-6-1), and\n  -- \"when your Leader is placed\" hears it (22-46-6-3). 22-46-4's once a turn\n  -- needs no count: once it has resolved the Leader is a Z-card, which the\n  -- third REFUSE already refuses, so a second [Z-Awaken] that turn is refused\n  -- by that reason rather than by the legacy `oncePerTurn` one.\n  offer: \"activate:main\"\n  REFUSE zone(area: zDeck) UNLESS count([self] IN you.zDeck) >= 1\n  REFUSE condition(text: \"your Leader is awakened and not yet a Z-Leader\") UNLESS all([leaderFlipped(), NOT count(\"Z-card\" IN you.leader) >= 1])\n  REFUSE target(reason: \"your Leader is not {line}\") UNLESS count(IN you.leader asPrinted) >= 1\n  label: \"Z-Awaken: {card} on your Leader\"\n  DO {\n    play(target: [self], onto: IN you.leader)\n  }\n\n-- 22-47\nDEFINE KEYWORD \"Z-Stack\"\n  TAKES (x: number)\n  text: \"When this Z-Card is placed on your Leader or into a Battle or Unison Area, put up to X cards matching the printed description from your Z-Deck underneath it. They become part of the card on top.\"\n  -- #155: a moment (`at:`), pended as the card is played and as it is placed\n  -- on the Leader, like the legacy `keywordTriggers` case. The candidates are\n  -- the Z-Deck cards the line's description matches (`asPrinted`), up to X of\n  -- them or none. One difference, recorded rather than copied: each card goes\n  -- straight under (23-2), where the legacy engine logs a move to the Battle\n  -- Area first and then lifts it out of the area again.\n  at: [played, leaderPlaced]\n  DO {\n    choose(sel: UP TO $x IN you.zDeck asPrinted, as: \"stack\", reason: \"[Z-Stack]: cards from your Z-Deck to place under this card\")\n    moveTo(target: $stack, to: under, under: [self])\n  }\n",
  "ops.rules": "-- The macros: every op the cards use that is not a primitive, written over\n-- the ones that are.\n--\n-- `docs/arena-ruleset-spec.md` §2 is the decision — nineteen primitives, and\n-- one `DEFINE OP` here for each of the thirty-one rows `OP_CLASS` marks\n-- *macro*. A macro is not a deletion: `power(…)` keeps its `OP_SCHEMA` row,\n-- keeps printing as itself and keeps round-tripping by that name; this file\n-- says only what it *means*, and `rulesets/expand.ts` is what lowers a program\n-- written in these ops to a program written in the primitives.\n--\n-- **Thirty of the thirty-one are declared; `mill` stays a native op, and the\n-- table below is why.** Writing a row that silently dropped an argument would\n-- be worse than none: it would validate, it would expand, the sweep in\n-- `scripts/verify/language.ts` would pass, and the rule it claimed to explain\n-- would be wrong. Each entry names what a row waited on and what answered it.\n--\n-- ── what each row waits on ────────────────────────────────────────────────\n--\n--   param     answered (#273): inside a DEFINE OP body `$name` may stand in\n--             every field position — a duration, a side, an area, a mode or\n--             any closed list (declared `word`), a list of strings\n--             (`strings`), a whole program (`ops`) — and in a selector's\n--             count, `TOP n`, side and area.\n--   count     answered (#137): a selector's `TOP n` and its plain `n IN …`\n--             count are one slot type, `count`, which a macro may fill with\n--             a `number` or an `amount` — X and `handUpTo(4)` included —\n--             because `draw`, `discard`, `damage` and `addLife` take `n` as\n--             an amount. No selector *runs* counted by an expression: the\n--             lowered move or choice is read back as the spelling it stands\n--             for first (`moveAs`, `discardAs`, `vm/script-schema.ts`).\n--   replace   answered (#125, #232, #436, and #137 for the two moments it\n--             added): `replace` is an op, its `event` names `attack` and\n--             `counter` beside the departures, and `replaceAs` reads an\n--             attack or a counter replaced by nothing back as\n--             `negateAttack`/`negateCounter`.\n--   subject   answered (#275): `modifyAttr` reaches a *player*\n--             (`energyMarkers`) and the *battle in progress* (`guard`) as\n--             well as a card, and the card's own six new attributes are\n--             declared in `attributes.rules` (spec §2.5-1, §2.5-3).\n--   branch    answered (#137): three rows mean different *acts* depending\n--             on which arguments the call gave, and a body may now say so —\n--             `GIVEN $p { … }` keeps its steps when the call gave `p` and it\n--             is not `false`, `GIVEN $p = word { … }` when `p` is that word,\n--             `UNLESS …` the other way (§3b; `Guard`, `lang/ast.ts`). The\n--             expander settles every guard before the body is a program.\n--             `resolvingPlay` is a replaced play with `instead` and the same\n--             play in another manner without it (9-6); `comboFrom` negates\n--             only when `negated`; `look` takes a `TOP` or a `BOTTOM` by\n--             `from`, and a whole area when `area` is not the deck.\n--   audience  answered (#137): `reveal` takes an `audience` (`you | both`,\n--             default `both`, 20-11) — `you` binds the cards and logs\n--             nothing — and `revealAs` reads the three shapes `look` lowers\n--             to back as `look`, whose case evaluates the count and takes one\n--             player's pile.\n--   maths     answered (#137): an amount subtracts — `a - n` is `a + -n`,\n--             the one operator's other sign, so nothing new is evaluated —\n--             and in a body the right of `+`/`-` may be a parameter, `life()`\n--             may take `$side`, and `TOP (…)` may hold a whole expression.\n--             \"Until you have n life\" is `TOP (life($side) - $n) IN\n--             $side.life`; `moveAs` reads that move back as `lifeDownTo`,\n--             whose case evaluates it and takes \"both players\" one pile at a\n--             time, which the count alone cannot.\n--   bind      `mill`'s `as` names the milled cards for a later clause outside\n--             the call (\"if that card is red\"). A string hole can carry the\n--             name into a `choose` or a `reveal` (`as: $as`), but the move\n--             after it would have to *read* that name as a ref, and a hole\n--             in a ref position is replaced by the argument — the string,\n--             not `{ var }` of it. The row waits on nothing this file's\n--             grammar could answer, so it stays a native op.\n--   cause     answered (#274) for `ko`, and (#137) for `comboFrom`: a move\n--             with the cause `combo` to the Combo Area, and the `negate`\n--             after it when the call said so, are folded back into one\n--             `comboFrom` by `comboFromAs` — its case is what checks 5-7-2\n--             (a battle on its master's side) and pends `youCombo` and\n--             `opponentCombos`, which a plain move neither checks nor pends.\n--\n-- ── the thirty-one macros ─────────────────────────────────────────────────\n--\n--   op                   lowers to                waits on\n--   draw                 move                     declared (#137)\n--   discard              choose + move            declared (#137)\n--   damage               move                     declared (#137)\n--   mill                 move                     bind — stays native\n--   addLife              move                     declared (#137)\n--   lifeDownTo           move                     declared (#137)\n--   energyMarker         modifyAttr               declared (#275)\n--   look                 reveal                   declared (#137)\n--   ko                   move                     declared (#274)\n--   switchMode           modifyAttr               declared (#275)\n--   power                modifyAttr               declared (#273)\n--   comboPower           modifyAttr               declared (#273)\n--   grant                modifyAttr               declared (#275)\n--   negateSkills         negate                   declared (#276)\n--   negateSkillsOfKind   negate                   declared (#276)\n--   negateChosenKeyword  negate                   declared (BT31-138)\n--   hidden               modifyAttr               declared (#275)\n--   redirectAttack       modifyAttr               declared (#275)\n--   comboFrom            move + negate            declared (#137)\n--   flip                 modifyAttr               declared (#275)\n--   faceUp               modifyAttr               declared (#275)\n--   addMarker            modifyAttr               declared (#275)\n--   removeMarker         modifyAttr               declared (#275)\n--   costReduction        costModifier             declared (#277)\n--   negateKeyword        negate                   declared (#276)\n--   gains                modifyAttr               declared (#275)\n--   replaceLeave         replace                  declared (#137)\n--   altCost              costModifier             declared (#277)\n--   resolvingPlay        replace                  declared (#137)\n--   negateAttack         replace                  declared (#137)\n--   negateCounter        replace                  declared (#137)\n--   negateOwnSkill       negate                   declared (#276)\n--   may                  chooseMode               declared (#273)\n--\n-- `mill` is the one row out, on `bind`, which no grammar change here would\n-- answer: it is a native op, and the record of why is the entry above.\n\n-- ── the two numbers a card changes (§2.3, 20-5) ────────────────────────────\n--\n-- A change to power or combo power is one act — one attribute of one card,\n-- by an expression, for a duration — and `modifyAttr` is that act. The two\n-- rows differ in nothing but which attribute they name, which is the whole of\n-- the argument the spec's table makes.\n\n-- §20-5 — \"+5000 power for the turn\", \"+X power\", \"power +5000 for each …\"\nDEFINE OP power\n  TAKES (target: ref, amount: amount, until: duration)\n  DO {\n    modifyAttr(target: $target, attr: power, amount: $amount, until: $until)\n  }\n  text: \"the card's power changes by the amount, for the duration\"\n  doc: \"what `power` means: one attribute of one card, changed by an expression until a moment\"\n\n-- §20-5 — \"+10000 combo power for the turn\"\nDEFINE OP comboPower\n  TAKES (target: ref, amount: amount, until: duration)\n  DO {\n    modifyAttr(target: $target, attr: comboPower, amount: $amount, until: $until)\n  }\n  text: \"the card's combo power changes by the amount, for the duration\"\n  doc: \"the same act as `power`, on the other printed number\"\n\n-- ── the offer to decline (§2.3, 20-16) ──────────────────────────────────────\n--\n-- \"You may draw 1 card\" is a `chooseMode` with two options, the second empty —\n-- the shape `chooseMode`'s own primitive case now reads (#273): it still asks\n-- when one branch is empty rather than dropping it, asks `chooser` in place of\n-- the master when the call names one, and binds `did(what: may)` from which\n-- branch was picked either way, so \"if you do\" / \"if you don't\" reads it.\n\n-- §20-16 — \"You may draw 1 card\", \"your opponent may KO 1 of their cards\"\nDEFINE OP may\n  TAKES (ops: ops, reason: string, chooser: side)\n  DO {\n    chooseMode(modes: [\"Do it\" $ops, \"Don't\" {}], reason: $reason, chooser: $chooser)\n  }\n  text: \"the chooser may do the program, or not\"\n  doc: \"what `may` means: `chooseMode` with the declined branch empty — the primitive is the general form, this is the printed shape\"\n\n-- ── a move told apart by its cause (§2.5-2, #274) ───────────────────────────\n--\n-- `damage`, `ko`, a plain `draw` and every other move that isn't just \"an\n-- effect moved a card\" are one primitive — `moveTo` — with `cause` naming\n-- which. `ko` came first (#274): its `target` is a `ref`. `draw`, `damage`\n-- and `addLife` followed once a selector's count could be handed an `amount`\n-- (#137, the `count` entry above): each is the top `n` cards of one pile,\n-- moved, and `moveAs` (`vm/script-schema.ts`) reads each of the three\n-- shapes back as its own spelling before either engine runs it — a draw from\n-- an empty deck, damage's own moments (21-3) and \"both players\" (the top `n`\n-- of *each* pile) are what those cases know and a plain move does not.\n-- `discard` is 20-7 written out: the hand's owner chooses, and the cards go —\n-- `discardAs` folds the two steps back into the one `discard` whose case asks\n-- each player in turn. `lifeDownTo` is the top `life - n` of a life, to the\n-- hand with no cause (1-13-2) — `moveAs` reads it back as the op whose case\n-- takes \"both players\" one pile at a time. `mill` stays native (`bind`).\n\n-- §20-5 — \"draw 1 card\", \"your opponent draws 2 cards\", \"draw X cards\",\n-- \"draw cards until you have 4 cards in your hand\"\nDEFINE OP draw\n  TAKES (n: amount, side: side)\n  DO {\n    moveTo(target: TOP $n IN $side.deck, to: hand, cause: draw)\n  }\n  text: \"the top cards of the player's deck move to their hand, as a draw\"\n  doc: \"what `draw` means: the general move, from the top of the deck, with the cause a draw carries\"\n\n-- §20-7 — \"discard 1 card from your hand\", \"your opponent chooses 1 card in\n-- their hand and discards it\", \"…to the Warp\"\nDEFINE OP discard\n  TAKES (n: amount, side: side, to: area)\n  DO {\n    choose(sel: $n IN $side.hand, as: \"discarded\", chooser: $side)\n    moveTo(target: $discarded, to: $to, reveal: true)\n  }\n  text: \"the hand's owner chooses that many of its cards, and they go to the Drop Area or the Warp\"\n  doc: \"what `discard` means: a choice the hand's owner makes, then the move — the one row over two primitives\"\n\n-- §21-3 — \"deal 1 damage to your opponent\"\nDEFINE OP damage\n  TAKES (n: amount, side: side)\n  DO {\n    moveTo(target: TOP $n IN $side.life, to: hand, cause: damage)\n  }\n  text: \"the top life cards of the player move to their hand, as damage\"\n  doc: \"what `damage` means: the general move, from the life, with the cause damage carries — never Critical (21-3)\"\n\n-- §3-9 — \"add the top card of your deck to your life\"\nDEFINE OP addLife\n  TAKES (n: amount, side: side)\n  DO {\n    moveTo(target: TOP $n IN $side.deck, to: life)\n  }\n  text: \"the top cards of the player's deck move to their life\"\n  doc: \"what `addLife` means: the general move, from the top of the deck to the Life Area\"\n\n-- §21-3-2 — \"add cards from your life to your hand until you have 3 life\"\nDEFINE OP lifeDownTo\n  TAKES (n: number, side: side)\n  DO {\n    moveTo(target: TOP (life($side) - $n) IN $side.life, to: hand)\n  }\n  text: \"the player's life cards go to their hand until that many remain\"\n  doc: \"what `lifeDownTo` means: the general move, from the top of the life, of as many cards as are over the count — never damage (1-13-2)\"\n\n-- §5-7 — \"use it in a combo from your Drop Area (with its skills negated)\".\n-- The move carries the cause a combo does; the negate is kept only when the\n-- call says `negated`. `comboFromAs` folds the two back into the one step\n-- whose case checks 5-7-2 and pends the combo moments.\nDEFINE OP comboFrom\n  TAKES (target: ref, negated: boolean)\n  DO {\n    moveTo(target: $target, to: combo, reveal: true, cause: combo)\n    GIVEN $negated {\n      negate(target: $target, what: skills)\n    }\n  }\n  text: \"the card joins the battle as a combo, its skills negated when the call says so\"\n  doc: \"what `comboFrom` means: a move to the Combo Area with the cause a combo carries, and a negate of the card's skills only when `negated`\"\n\n-- §1-13, §21-3-3 — \"KO 1 of your opponent's Battle Cards.\" To the owner's\n-- Drop with the cause \"when you KO'd a card\" (20-16's `did`) and \"when this\n-- card is KO'd\" (9-6) both read. [Indestructible], \"can't be KO'd by\n-- skills\" and a KO's own replacement offers are the general move's business\n-- (9-10) — the macro says only the destination and the cause.\nDEFINE OP ko\n  TAKES (target: ref)\n  DO {\n    moveTo(target: $target, to: drop, cause: ko)\n  }\n  text: \"the card moves to its owner's Drop Area\"\n  doc: \"what `ko` means: the general move, to the Drop, with the cause every KO carries\"\n\n-- ── a rule that stops applying (§2.2, 9-1-5, #276) ──────────────────────────\n--\n-- Five spellings, one primitive: `negate(target, what: skills | kind | keyword\n-- | own, kind?, keyword?, chosen?, until?)` reads a card's skills, a printed\n-- kind of them, a named keyword everywhere, a keyword the master picks, or the\n-- skill resolving now, and stops it for a duration. `negateAs` (`vm/script-schema.ts`) is the interpreter's\n-- own reading in the other direction — a `negate(…)` call read back as one of\n-- the four — and each row here is built to invert it exactly, so a program\n-- written the declared way and one written the primitive's own way say the\n-- same thing (`verify/vm.ts`'s existing macro/primitive parity block).\n-- `comboFrom`'s negate half is declared beside the moves, above (#137).\n\n-- §9-1-5 — \"negate that card's skills for the turn\"\nDEFINE OP negateSkills\n  TAKES (target: ref, until: duration)\n  DO {\n    negate(target: $target, what: skills, until: $until)\n  }\n  text: \"the target's skills stop applying, for the duration\"\n  doc: \"what `negateSkills` means: every skill of one card, negated (9-1-5)\"\n\n-- §9-1-5 — \"negate that card's [Auto] skill for the turn\"\nDEFINE OP negateSkillsOfKind\n  TAKES (target: ref, kind: word, until: duration)\n  DO {\n    negate(target: $target, what: kind, kind: $kind, until: $until)\n  }\n  text: \"the target's skills of the printed kind stop applying, for the duration\"\n  doc: \"what `negateSkillsOfKind` means: one printed kind of skill of one card, negated — not the whole card (9-1-5)\"\n\n-- §9-1-5 — \"negate this card's [Energy-Exhaust] skill in all areas\"\nDEFINE OP negateKeyword\n  TAKES (keyword: word, target: ref)\n  DO {\n    negate(target: $target, what: keyword, keyword: $keyword)\n  }\n  text: \"the target loses the named keyword skill\"\n  doc: \"what `negateKeyword` means: one named keyword taken away, wherever the card sits — no duration of its own, unlike the other three\"\n\n-- §9-1-5 — \"choose up to 1 keyword skill on your opponent's Battle Card or\n-- Unison and negate that skill for the turn\" (BT31-138): the keyword is the\n-- master's pick as the step resolves, among those the target has in force.\nDEFINE OP negateChosenKeyword\n  TAKES (target: ref, until: duration)\n  DO {\n    negate(target: $target, what: keyword, chosen: true, until: $until)\n  }\n  text: \"the master picks one keyword skill the target has, and it stops applying, for the duration\"\n  doc: \"what `negateChosenKeyword` means: one keyword skill, picked as the step resolves among those the target cards have in force, negated on its card for the duration (9-1-5)\"\n\n-- §9-1-5 — \"negate this skill for the turn / battle / game\"\nDEFINE OP negateOwnSkill\n  TAKES (until: duration)\n  DO {\n    negate(what: own, until: $until)\n  }\n  text: \"this skill does not happen again, for the duration\"\n  doc: \"what `negateOwnSkill` means: the skill resolving now, negated for a span read off its own card — never a target, the way the other three take one\"\n\n-- ── a price is not a number (§2.5-4, #277) ──────────────────────────────────\n--\n-- `costModifier(target, amount?, what?, colors?, skillKind?, pay?, n?, for?,\n-- alt?, orbs?, until?, onto?, uses?)` is the one primitive under both spellings —\n-- `costModifierAs` (`vm/script-schema.ts`) reads a call back as whichever\n-- it stands for, and each row here is built to invert it exactly: `pay`\n-- present means `altCost` (the price replaced), absent means `costReduction`\n-- (the price's number changed). The rules engine reads only the reduction\n-- half, through the `costOf`/`specifiedCost` layers `LAYER_KINDS` pairs it\n-- with (`vm/effects.ts`); `altCost` stays a documented gap there (#149).\n\n-- §20-21 — \"reduce the energy cost of your <Son Goku> cards in your hand by\n-- 1\", \"…combo cost…\", \"…Z-Energy cost…\", the specified (coloured) half\n-- (owner's BT19-039 ruling), and a skill's own orb price scoped by kind.\n-- `onto` scopes an [Evolve] price change to the card it is played onto\n-- (EX03-16: \"when evolving this card into a <Broly> …\", `onto: [self]`).\nDEFINE OP costReduction\n  TAKES (target: ref, amount: amount, what: word, skillKind: word, colors: colors, until: duration, onto: ref, uses: number)\n  DO {\n    costModifier(target: $target, amount: $amount, what: $what, skillKind: $skillKind, colors: $colors, until: $until, onto: $onto, uses: $uses)\n  }\n  text: \"the target's price changes by the amount\"\n  doc: \"what `costReduction` means: the general price change, with nothing about what replaces it\"\n\n-- §5-3 — \"you can activate this card's [Counter] skill for nothing / by\n-- adding cards from your life to your hand / by a reduced energy price /\n-- by a program instead\"\nDEFINE OP altCost\n  TAKES (pay: word, n: number, for: word, ops: ops, orbs: colors, target: ref, until: duration)\n  DO {\n    costModifier(target: $target, pay: $pay, n: $n, for: $for, alt: $ops, orbs: $orbs, until: $until)\n  }\n  text: \"the target's price is replaced\"\n  doc: \"what `altCost` means: the general price change, naming what replaces the price rather than a number it moves by\"\n\n-- ── a player and the battle in progress, as subjects (§2.5-1, §2.5-3, #275) ─\n--\n-- `modifyAttr` reached one card and six attributes before this issue; the\n-- nine rows below are what unblocked once it also reached a *player*\n-- (`side`, for `energyMarkers`) and the *battle in progress* (`target` read\n-- as the value being set rather than a locator — there is only one), and\n-- once `mode`, `markers`, `keywords`, `hidden`, `faceUp` and `flipped` were\n-- declared card attributes (`attributes.rules`). `modifyAttrAs`\n-- (`vm/script-schema.ts`) is the one reading of each spelling, so a\n-- program written either way runs the same case, puts the same effect in\n-- force (or none) and reads in the same words — the precedent `negateAs`\n-- and `costModifierAs` set for their own primitives.\n\n-- §1-14 — \"gain 1 energy marker\", \"your opponent gains 2 energy markers\"\nDEFINE OP energyMarker\n  TAKES (n: amount, side: side)\n  DO {\n    modifyAttr(subject: player, side: $side, attr: energyMarkers, amount: $n)\n  }\n  text: \"the named player's energy markers change by the amount\"\n  doc: \"what `energyMarker` means: `modifyAttr`'s first widened subject — a player rather than a card (spec §2.5-1)\"\n\n-- §8-1, §22-4-2 — \"switch the target of the attack to it\"\nDEFINE OP redirectAttack\n  TAKES (target: ref)\n  DO {\n    modifyAttr(subject: battle, attr: guard, target: $target)\n  }\n  text: \"the target of the attack switches to the named card\"\n  doc: \"what `redirectAttack` means: `modifyAttr`'s other widened subject — the battle in progress, which has one attribute and needs no locator of its own (spec §2.5-1)\"\n\n-- §1-10 — \"switch it to Rest Mode\", \"switch it to Active Mode\"\nDEFINE OP switchMode\n  TAKES (target: ref, mode: word)\n  DO {\n    modifyAttr(target: $target, attr: mode, mode: $mode)\n  }\n  text: \"the card switches to the named mode\"\n  doc: \"what `switchMode` means: one of the six card attributes spec §2.5-3 adds — set to the named mode, no duration of its own (1-10)\"\n\n-- §23-5 — \"switch it to Hidden Mode\", \"switch it to Revealed Mode\"\nDEFINE OP hidden\n  TAKES (target: ref, hidden: boolean)\n  DO {\n    modifyAttr(target: $target, attr: hidden, flag: $hidden)\n  }\n  text: \"the card switches to Hidden Mode or Revealed Mode, as named\"\n  doc: \"what `hidden` means: set to the named boolean, no duration of its own (23-5)\"\n\n-- §3-9-2-1 — \"flip up to 1 card in your life face up\", \"…face down\"\nDEFINE OP faceUp\n  TAKES (target: ref, faceUp: boolean)\n  DO {\n    modifyAttr(target: $target, attr: faceUp, flag: $faceUp)\n  }\n  text: \"the card in life turns face up or face down, as named\"\n  doc: \"what `faceUp` means: set to the named boolean, no duration of its own (3-9-2-1)\"\n\n-- §22-2-4 — \"you may flip this card over\"\nDEFINE OP flip\n  TAKES (target: ref)\n  DO {\n    modifyAttr(target: $target, attr: flipped)\n  }\n  text: \"the card turns to its back side\"\n  doc: \"what `flip` means: the one card attribute with no value field of its own to name — the primitive's own case reads what a flip means (22-2-4)\"\n\n-- §1-11 — \"add 1 marker to this card\"\nDEFINE OP addMarker\n  TAKES (target: ref, n: amount)\n  DO {\n    modifyAttr(target: $target, attr: markers, amount: $n, sign: add)\n  }\n  text: \"the card's markers increase by the amount\"\n  doc: \"what `addMarker` means: a delta on the one attribute a marker count is (1-11); `sign` is which way `removeMarker` beside it moves the same delta\"\n\n-- §1-11 — \"remove 1 marker from this card\"\nDEFINE OP removeMarker\n  TAKES (target: ref, n: amount)\n  DO {\n    modifyAttr(target: $target, attr: markers, amount: $n, sign: remove)\n  }\n  text: \"the card's markers decrease by the amount\"\n  doc: \"the same act as `addMarker`, the other way (1-11)\"\n\n-- §9-1-3, §22-1 — \"this card gains [Blocker] for the turn\"\nDEFINE OP grant\n  TAKES (target: ref, keyword: keyword, until: duration)\n  DO {\n    modifyAttr(target: $target, attr: keywords, keyword: $keyword, until: $until)\n  }\n  text: \"the target gains the named keyword skill, for the duration\"\n  doc: \"what `grant` means: one card attribute, by the keyword it counts as having — `until` left out means the keyword is printed rather than granted, which nothing calls this row for (9-1-3, 22-1)\"\n\n-- §20-1 — \"this card also counts as ≪Saiyan≫\", \"…is also treated as\n-- red\", \"…is also treated as {Planet Namek}\"\nDEFINE OP gains\n  TAKES (target: ref, traits: strings, characters: strings, colors: strings, names: strings)\n  DO {\n    modifyAttr(target: $target, attr: traits, values: $traits)\n    modifyAttr(target: $target, attr: characters, values: $characters)\n    modifyAttr(target: $target, attr: colors, values: $colors)\n    modifyAttr(target: $target, attr: alsoNames, values: $names)\n  }\n  text: \"the card also counts as the named traits, characters, colours and names, wherever it is\"\n  doc: \"what `gains` means: `modifyAttr`'s general row, one call per list attribute — a call that leaves one out leaves that call's own \\\"values\\\" out too, which the static reader (`collectStatics`/`permanents`) already treats as none of that list (docs/arena-ruleset-spec.md §2.3)\"\n\n-- ── an event in another's place (§2.2, 9-10, #137) ──────────────────────────\n--\n-- `replace(event, with, by?, bySide?, to?, optional?, target?)` is the one\n-- primitive under three spellings here. `replaceLeave` is its redirect form:\n-- the departure happens, to somewhere else, and `with` is one move of the\n-- card itself — the shape `collectStatics` and `vm/effects.ts` already read\n-- as a redirect, so a [Permanent] written either way stands the same offer\n-- under the same kind. `by: ko` on a `leave` is the same moment as the `ko`\n-- event (the readers already store both as `by: \"ko\"`); it is spelled that\n-- way because a template cannot pick its `event` by the call's `by`. A\n-- `replaceLeave` to `play` or `under` — which the compiler never writes, and\n-- the sweep proves no record carries — would lower to a substitute rather\n-- than the native op's mapped redirect, the one boundary of this row.\n--\n-- `negateAttack` and `negateCounter` are the attack in progress and the\n-- [Counter] being answered, each replaced by nothing. Neither is a standing\n-- offer: `replaceAs` reads the call back as the spelling it stands for, so\n-- their own cases — 20-16's \"if you negated a Leader Card's attack\", 9-7's\n-- counter in flight — stay the one reading of either.\n--\n-- `resolvingPlay` is the play being resolved (9-6), replaced: by a move of\n-- the card elsewhere when the call names `instead`, and otherwise by the same\n-- play in another manner — rested, or its skills negated for the turn. The\n-- `GIVEN`/`UNLESS` guards are the header's `branch`; `replaceAs` reads both\n-- shapes back as `resolvingPlay`, whose case is the one reading.\n\n-- §9-10 — \"if this card would be KO'd, place it in your Warp instead\", \"…\n-- would be removed from the Battle Area by your opponent's skill, you may\n-- return it to your hand instead\"\nDEFINE OP replaceLeave\n  TAKES (to: area, by: word, bySide: word, mode: word, optional: boolean, target: ref)\n  DO {\n    replace(event: leave, by: $by, bySide: $bySide, optional: $optional, target: $target, with: { moveTo(target: [subject], to: $to, mode: $mode) })\n  }\n  text: \"if the card would leave the Battle Area, it goes to the named area instead\"\n  doc: \"what `replaceLeave` means: `replace`'s redirect form — the departure happens, to another area\"\n\n-- §8-1-6-1 — \"negate the attack\"\nDEFINE OP negateAttack\n  TAKES ()\n  DO {\n    replace(event: attack, with: {})\n  }\n  text: \"the attack in progress resolves to nothing\"\n  doc: \"what `negateAttack` means: the attack, replaced by nothing\"\n\n-- §9-7 — \"negate the [Counter] skill\"\nDEFINE OP negateCounter\n  TAKES ()\n  DO {\n    replace(event: counter, with: {})\n  }\n  text: \"the [Counter] this one answers resolves to nothing\"\n  doc: \"what `negateCounter` means: the counter being answered, replaced by nothing (9-7)\"\n\n-- §9-6 — \"negate the play of that card and place it at the bottom of its\n-- owner's deck\", \"it's played in Rest Mode\", \"…with its skills negated\"\nDEFINE OP resolvingPlay\n  TAKES (instead: area, position: word, mode: word, negated: boolean)\n  DO {\n    GIVEN $instead {\n      replace(event: play, with: { moveTo(target: [resolving], to: $instead, position: $position) })\n    }\n    UNLESS $instead {\n      GIVEN $negated {\n        replace(event: play, with: { play(target: [resolving], mode: $mode, negated: turn) })\n      }\n      UNLESS $negated {\n        replace(event: play, with: { play(target: [resolving], mode: $mode) })\n      }\n    }\n  }\n  text: \"the play being resolved goes elsewhere instead, or happens in another manner\"\n  doc: \"what `resolvingPlay` means: the play replaced — by a move of the card with `instead`, by the same play rested or negated for the turn without it ([Counter: Play] only, 9-6)\"\n\n-- ── what a player sees (§2.2, 20-11, #137) ──────────────────────────────────\n--\n-- Looking is revealing to one player. `reveal`'s `audience: you` binds the\n-- cards and logs nothing; `revealAs` reads each of the three shapes below\n-- back as `look`, whose case evaluates the count and takes one player's pile.\n-- A whole area's count is not read — the area is the cards.\n\n-- §20-11 — \"look at the top 3 cards of your deck\", \"…the bottom card…\",\n-- \"look at your opponent's hand\"\nDEFINE OP look\n  TAKES (n: amount, as: string, side: side, from: word, area: area)\n  DO {\n    GIVEN $area = deck {\n      GIVEN $from = top {\n        reveal(sel: TOP $n IN $side.deck, as: $as, audience: you)\n      }\n      GIVEN $from = bottom {\n        reveal(sel: BOTTOM $n IN $side.deck, as: $as, audience: you)\n      }\n    }\n    UNLESS $area = deck {\n      reveal(sel: IN $side.$area, as: $as, audience: you)\n    }\n  }\n  text: \"the cards are shown to the player alone, and stay where they are\"\n  doc: \"what `look` means: a reveal whose audience is you — the top or bottom of a deck, or a whole other area (20-11)\"\n",
  "prompts.rules": "-- One DEFINE PROMPT per Prompt[\"kind\"] (PROMPT_KINDS, vm/script-schema.ts,\n-- 18 entries, in that order), with the question template questionFor\n-- (view.ts, shared with vm/view.ts on the rules engine) uses today.\n--\n-- Declared rather than hand-written by the owner's decision on #131/#135\n-- (20 Sep 2026): DEFINE PROMPT is a declaration of its own, not a field of\n-- DEFINE ACTION. Consumed since #160: `prompt-words.ts` reads the question and\n-- hint of the eleven fixed kinds from here, and `questionFor`/`promptView`\n-- read the hint of the others, so a word edited here is a word the prompt bar\n-- says.\n--\n-- Eleven kinds ask a question that never varies (FIXED_PROMPT_KINDS in\n-- prompt-words.ts) — read from here verbatim. The other seven build their\n-- question from the situation (a card's name, a cost, a count): `question:`\n-- carries the same template questionFor writes, in prose naming the value\n-- the way a DEFINE OP's own text: names a parameter (\"the amount\") rather\n-- than as a hole a program could fill — turning it into one a client could\n-- read is Stage 8's wiring, not this declaration. `chooseCards`'s question,\n-- `chooseMode`'s and `replaceMove`'s are the engine's own text verbatim, with\n-- no template of their own to add to it; `referee`'s hint is the same, so it\n-- carries none here.\n\nDEFINE PROMPT chooseFirst\n  question: \"You won the flip. Who goes first?\"\n  hint: \"The second player starts with one energy marker.\"\n\nDEFINE PROMPT mulligan\n  question: \"Keep this hand?\"\n  hint: \"You may redraw six cards once (6-2-1-9).\"\n\nDEFINE PROMPT charge\n  question: \"Charge one card as energy?\"\n  hint: \"Tap a card in hand, or skip.\"\n\nDEFINE PROMPT main\n  question: \"Your Main Phase.\"\n  hint: \"Play cards, attack, or end the turn.\"\n\nDEFINE PROMPT combo\n  question: \"Combo? Tap a glowing card.\"\n  hint: \"Each adds its combo power and costs its combo cost.\"\n\nDEFINE PROMPT blocker\n  question: \"Block with one of these?\"\n  hint: \"[Blocker] rests the card and makes it the guard instead.\"\n\nDEFINE PROMPT counter\n  question: \"Play a counter?\"\n  hint: \"Counter cards are activated from hand and go to the Drop.\"\n\n-- The candidates' own reason, read verbatim off the choice being asked for —\n-- no fixed wording of its own.\nDEFINE PROMPT orderPending\n  question: \"Which skill resolves first?\"\n  hint: \"Several of your skills triggered at once.\"\n\nDEFINE PROMPT chooseCards\n  question: \"the reason given for the choice\"\n  hint: \"Choose the minimum to the maximum, or exactly the minimum when the two are equal.\"\n\nDEFINE PROMPT chooseMode\n  question: \"the reason given for the choice\"\n  hint: \"The card offers these; exactly one happens (20-2).\"\n\nDEFINE PROMPT replaceMove\n  question: \"the reason given for the replacement\"\n  hint: \"Choose one replacement, or let the original move happen.\"\n\nDEFINE PROMPT zEnergyFromCombo\n  question: \"Send one combo card to Z-Energy?\"\n  hint: \"At the end of a battle, one card may go there instead of the Drop.\"\n\nDEFINE PROMPT optionalCost\n  question: \"Pay the skill's cost for the card?\"\n  hint: \"An [Auto] skill's cost may be declined; then it does not resolve.\"\n\nDEFINE PROMPT payCost\n  question: \"Which energy do you rest to pay the cost?\"\n  hint: \"The colours you keep active decide what you can still do this turn.\"\n\nDEFINE PROMPT offering\n  question: \"[Offering]: drop one life, or let them draw two?\"\n\nDEFINE PROMPT empowerCarry\n  question: \"[Empower]: carry up to the maximum marker or markers from the card being replaced to the card played over it?\"\n  hint: \"You may carry fewer than the maximum, or none at all (22-45-3).\"\n\n-- The hint is the unsupported request's own detail, read verbatim — no fixed\n-- wording of its own, unlike every prompt above.\nDEFINE PROMPT referee\n  question: \"Claude is ruling on the card's name…\"\n\nDEFINE PROMPT gameOver\n  question: \"The game is over.\"\n",
  "triggers.rules": "-- ───────────────────────────────────────────────────────────────────────────\n-- The moments an [Auto] or a [Counter] answers to (manual 9-6), as the events\n-- that *are* them.\n--\n-- A trigger is a name in the legacy engine, matched against the event log by\n-- TypeScript. Here it is an event pattern, so a game can declare its own\n-- moments without code — and so the engine's moments can be read against the\n-- manual rather than against `pendTriggers`.\n--\n-- Four conventions hold across the file.\n--\n--   ON <event>(field: value, …)\n--     The event and the fields that have to match. Event names are the\n--     definition's own; which of them a game fires is Stage 4's business.\n--     Only `from`, `to`, `in`, `area` and `zone` name a DEFINE ZONE and are\n--     checked by the loader — every other argument is a word about the event\n--     itself, so `attackDeclared(target: leader)` is a part in the attack and\n--     not a place.\n--\n--   watcher: controller | opponent | both\n--     Whose cards in play are asked, when the moment is not the answering\n--     card's own. `controller` is the side the event is about (the moved\n--     card's master, the damaged player); `opponent` is the other one.\n--     Left out, only the card the event is about answers.\n--\n--   WHERE\n--     A condition on the answering side rather than on the event.\n--     `isTurnPlayer(who: you)` is what \"your Charge Phase\" means on a card,\n--     and \"your opponent's turn\" is the same condition from the other chair\n--     (7-1) — never a duration.\n--\n--   BIND\n--     What the event's card is called inside the program: \"self\" when the\n--     moment happened to the answering card, \"subject\" when it happened to\n--     another card that the answering card is watching. A watcher list that\n--     includes the card itself (a Unison paying its own [Spirit Boost], a\n--     Life card turned face up) binds \"subject\" all the same — there it is\n--     the same card.\n--\n-- The names are the `Trigger` union's, and `text:` is the record's WHEN in\n-- words, so `scripts/verify/rulesets.ts` can hold the two to one list.\n-- The five `counter:*` declarations at the foot are the counter windows\n-- (4-3, 9-7): the moments a [Counter] answers to rather than an [Auto], and\n-- the only names here a card's WHEN never says.\n-- ───────────────────────────────────────────────────────────────────────────\n\n-- ── playing and placing ────────────────────────────────────────────────────\n\n-- §6-2-4 — when your Leader is placed\nDEFINE TRIGGER leaderPlaced\n  ON moved(to: leader)\n  BIND \"self\"\n  text: \"when your Leader is placed\"\n\n-- §9-6-9-4 — when this card is played\nDEFINE TRIGGER played\n  ON moved(asPlay: true, to: [battle, unison])\n  BIND \"self\"\n  text: \"when this card is played\"\n\n-- §22-15 — when this card is played using [Over Realm]: the same arrival,\n-- made by [Over Realm]'s own move, which says so on its `play` (`using:` in\n-- keywords.rules). An ordinary play carries no `using`, so it never matches.\nDEFINE TRIGGER playedUsingOverRealm\n  ON moved(asPlay: true, to: battle, using: \"Over Realm\")\n  BIND \"self\"\n  text: \"when this card is played using [Over Realm]\"\n\n-- §5-5 — when you play a card\nDEFINE TRIGGER youPlayed\n  ON moved(asPlay: true, to: [battle, unison], watcher: controller)\n  BIND \"subject\"\n  text: \"when you play a card\"\n\n-- §5-5 — when your opponent plays a card\nDEFINE TRIGGER opponentPlayed\n  ON moved(asPlay: true, to: [battle, unison], watcher: opponent)\n  BIND \"subject\"\n  text: \"when your opponent plays a card\"\n\n-- §5-5-4 — when this card is placed in a Battle Area. 5-5-1: playing a card\n-- places it in the Battle Area, so a play is one of the ways this happens and\n-- the pattern does not ask `asPlay` (owner's ruling, 2 Oct 2026). A skill whose\n-- record also says `played` answers the one arrival once (`vm/triggers.ts`).\nDEFINE TRIGGER placed\n  ON moved(to: battle)\n  BIND \"self\"\n  text: \"when this card is placed in a Battle Area\"\n\n-- §5-5-4 — when a card is placed in your Battle Area: the same arrival,\n-- watched by the cards of the side whose Battle Area it arrived in. Played or\n-- placed by a skill alike (5-5-1, owner's ruling of 2 Oct 2026). The card is\n-- the subject, and what the card says about it (\"a {Scouter}\", \"one of your\n-- blue Z-Extras\", BT23-066, BT22-032b) is a condition on that subject.\nDEFINE TRIGGER yourCardPlaced\n  ON moved(to: battle, watcher: controller)\n  BIND \"subject\"\n  text: \"when a card is placed in your Battle Area\"\n\n-- ── battles (8-1 … 8-5) ────────────────────────────────────────────────────\n\n-- §8-1-3 — when this card attacks\nDEFINE TRIGGER attacks\n  ON attackDeclared(role: attacker)\n  BIND \"self\"\n  text: \"when this card attacks\"\n\n-- §8-1-3 — when this card is attacked\nDEFINE TRIGGER attacked\n  ON attackDeclared(role: target)\n  BIND \"self\"\n  text: \"when this card is attacked\"\n\n-- §8-1-3 — when your opponent attacks\n--\n-- `role: attacker` is #150's addition, the first stage to actually fire an\n-- `attackDeclared` moment: a battle names two cards, the attacker and the\n-- guard, and `vm/battle.ts` fires one moment for each so `attacks`/`attacked`\n-- can each `BIND \"self\"` to the right one. Without a role narrowing this\n-- pattern, the *guard's* own moment would match it too (its `watcher:\n-- opponent` asks nothing about which card the moment is about, only who is\n-- asked), which would pend this trigger a second time off the wrong subject.\nDEFINE TRIGGER opponentAttacks\n  ON attackDeclared(role: attacker, watcher: opponent)\n  BIND \"subject\"\n  text: \"when your opponent attacks\"\n\n-- §8-1-3 — when your Leader is attacked\nDEFINE TRIGGER yourLeaderAttacked\n  ON attackDeclared(target: leader, watcher: controller)\n  BIND \"subject\"\n  text: \"when your Leader is attacked\"\n\n-- §8-2 — at the start of the offense step\nDEFINE TRIGGER offenseStart\n  ON stepStart(step: offense)\n  WHERE isTurnPlayer(who: you)\n  BIND \"self\"\n  text: \"at the start of the offense step\"\n\n-- §8-3 — at the start of the defense step\nDEFINE TRIGGER defenseStart\n  ON stepStart(step: defense)\n  WHERE isTurnPlayer(who: opponent)\n  BIND \"self\"\n  text: \"at the start of the defense step\"\n\n-- §8-4 — at the start of the damage step\nDEFINE TRIGGER damageStart\n  ON stepStart(step: damage, watcher: both)\n  BIND \"self\"\n  text: \"at the start of the damage step\"\n\n-- §8-5 — at the end of the battle\nDEFINE TRIGGER battleEnd\n  ON stepStart(step: battleEnd, watcher: both)\n  BIND \"self\"\n  text: \"at the end of the battle\"\n\n-- ── KOs (5-12, 21-14) ──────────────────────────────────────────────────────\n\n-- §5-12 — when this card is KO'd\n--\n-- `role: koed` is #150's addition, for the same reason `opponentAttacks`\n-- above needed one: a KO names two cards, the one that left and the one that\n-- caused it (`kos`, `role: cause`, already declared), and `vm/battle.ts`\n-- fires one `ko` moment for each. Left bare, this pattern's empty `ON ko`\n-- would match *either* moment — the koed card's own and the attacker's —\n-- since a pattern with no arguments is true of any event carrying that name;\n-- naming the koed card's own role is what keeps it from also asking the\n-- attacker \"were you KO'd\". `to: drop` is 9-1-3-1's derived exception,\n-- exactly as `droppedFromBattle` below reads it for a skill's own move: a\n-- card asking whether it was just KO'd is asked about its own departure\n-- *after* it has already landed in the Drop, so the pattern has to name the\n-- place its skills are still valid in reacting to, the same as any other\n-- \"fires while the card is elsewhere\" moment.\nDEFINE TRIGGER koed\n  ON ko(role: koed, to: drop)\n  BIND \"self\"\n  text: \"when this card is KO'd\"\n\n-- §21-14 — when this card KOs a card\nDEFINE TRIGGER kos\n  ON ko(role: cause)\n  BIND \"self\"\n  text: \"when this card KOs a card\"\n\n-- §21-14 — when one of your cards is KO'd\nDEFINE TRIGGER yourCardKoed\n  ON ko(role: koed, watcher: controller)\n  BIND \"subject\"\n  text: \"when one of your cards is KO'd\"\n\n-- §21-14 — when an opponent's card is KO'd\nDEFINE TRIGGER opponentCardKoed\n  ON ko(role: koed, watcher: opponent)\n  BIND \"subject\"\n  text: \"when an opponent's card is KO'd\"\n\n-- ── leaving a Battle Area (3-1, 9-6-9) ─────────────────────────────────────\n\n-- §3-1-5 — when this card is removed from a Battle Area by a skill\nDEFINE TRIGGER removedFromBattle\n  ON moved(by: skill, from: battle)\n  BIND \"self\"\n  text: \"when this card is removed from a Battle Area by a skill\"\n\n-- §3-1-5 — when this card is removed from a Battle Area by an opponent's skill\nDEFINE TRIGGER removedByOpponent\n  ON moved(by: skill, byOpponent: true, from: battle)\n  BIND \"self\"\n  text: \"when this card is removed from a Battle Area by an opponent's skill\"\n\n-- §3-1-5 — when a skill sends this card from a Battle Area to the Drop\nDEFINE TRIGGER droppedFromBattle\n  ON moved(by: skill, from: battle, to: drop)\n  BIND \"self\"\n  text: \"when a skill sends this card from a Battle Area to the Drop\"\n\n-- §20-7 — when a skill sends this card from your hand to the Drop: a\n-- discard by a skill's effect or as its cost (1-6, 1-7-1, 20-7-4). Pended by\n-- name from a skill's own move, like `droppedFromBattle` above; a card leaving\n-- the hand by the rules (an Extra after it is activated, 12-2-2) says no\n-- `by: skill` and is not this.\nDEFINE TRIGGER droppedFromHand\n  ON moved(by: skill, from: hand, to: drop)\n  BIND \"self\"\n  text: \"when a skill sends this card from your hand to the Drop\"\n\n-- §3-1-5 — when this card goes from a Battle Area to the Drop\nDEFINE TRIGGER leftBattleToDrop\n  ON moved(from: battle, to: drop)\n  BIND \"self\"\n  text: \"when this card goes from a Battle Area to the Drop\"\n\n-- §9-6-9-3 — when this card goes from a Battle Area to the Drop in Hidden\n-- Mode. A card that moves face down answers to no other moment of its own\n-- (`matchTriggers`); this is the \"unless specified otherwise\" (BT28-117).\nDEFINE TRIGGER hiddenToDrop\n  ON moved(from: battle, to: drop, hidden: true)\n  BIND \"self\"\n  text: \"when this card goes from a Battle Area to the Drop in Hidden Mode\"\n\n-- ── damage and life (5-10, 3-9, 21-3) ──────────────────────────────────────\n\n-- §5-10 — when this card deals damage\nDEFINE TRIGGER dealtDamage\n  ON damage(role: source)\n  BIND \"self\"\n  text: \"when this card deals damage\"\n\n-- §21-3 — when you take damage from a skill\nDEFINE TRIGGER youTookDamage\n  ON damage(by: skill, watcher: controller)\n  BIND \"subject\"\n  text: \"when you take damage from a skill\"\n\n-- §21-3 — when your opponent takes damage from a skill\nDEFINE TRIGGER opponentTookDamage\n  ON damage(by: skill, watcher: opponent)\n  BIND \"subject\"\n  text: \"when your opponent takes damage from a skill\"\n\n-- §3-9 — when a card leaves your life\nDEFINE TRIGGER lifeLeft\n  ON moved(from: life, watcher: controller)\n  BIND \"subject\"\n  text: \"when a card leaves your life\"\n\n-- §3-9-2-1 — when a card in your life is flipped face up\nDEFINE TRIGGER flippedFaceUp\n  ON faceUpTurned(in: life, watcher: controller)\n  BIND \"subject\"\n  text: \"when a card in your life is flipped face up\"\n\n-- ── the turn (7-1 … 7-4) ───────────────────────────────────────────────────\n\n-- §7-2 — at the start of your Charge Phase\nDEFINE TRIGGER chargeStart\n  ON phaseStart(phase: charge)\n  WHERE isTurnPlayer(who: you)\n  BIND \"self\"\n  text: \"at the start of your Charge Phase\"\n\n-- §7-1 — at the start of your opponent's turn\nDEFINE TRIGGER opponentTurnStart\n  ON phaseStart(phase: charge)\n  WHERE isTurnPlayer(who: opponent)\n  BIND \"self\"\n  text: \"at the start of your opponent's turn\"\n\n-- §7-3 — at the start of your Main Phase\nDEFINE TRIGGER mainStart\n  ON phaseStart(phase: main)\n  WHERE isTurnPlayer(who: you)\n  BIND \"self\"\n  text: \"at the start of your Main Phase\"\n\n-- §7-3 — at the start of your opponent's Main Phase\nDEFINE TRIGGER opponentMainStart\n  ON phaseStart(phase: main)\n  WHERE isTurnPlayer(who: opponent)\n  BIND \"self\"\n  text: \"at the start of your opponent's Main Phase\"\n\n-- §7-3 — at the end of your Main Phase\nDEFINE TRIGGER mainEnd\n  ON phaseEnd(phase: main)\n  WHERE isTurnPlayer(who: you)\n  BIND \"self\"\n  text: \"at the end of your Main Phase\"\n\n-- §7-4 — at the end of your turn\nDEFINE TRIGGER turnEnd\n  ON phaseStart(phase: end)\n  WHERE isTurnPlayer(who: you)\n  BIND \"self\"\n  text: \"at the end of your turn\"\n\n-- §7-1 — at the end of your opponent's turn\nDEFINE TRIGGER opponentTurnEnd\n  ON phaseStart(phase: end)\n  WHERE isTurnPlayer(who: opponent)\n  BIND \"self\"\n  text: \"at the end of your opponent's turn\"\n\n-- ── combos (5-7, 8-5-8) ────────────────────────────────────────────────────\n\n-- §8-5-8 — when this card is used in a combo\nDEFINE TRIGGER comboed\n  ON moved(from: combo)\n  BIND \"self\"\n  text: \"when this card is used in a combo\"\n\n-- §5-7 — when you combo\nDEFINE TRIGGER youCombo\n  ON comboUsed(watcher: controller)\n  BIND \"subject\"\n  text: \"when you combo\"\n\n-- §5-7 — when your opponent combos\nDEFINE TRIGGER opponentCombos\n  ON comboUsed(watcher: opponent)\n  BIND \"subject\"\n  text: \"when your opponent combos\"\n\n-- ── keyword activations (22) ───────────────────────────────────────────────\n\n-- §22-4 — when this card activates [Blocker]\nDEFINE TRIGGER blockerUsed\n  ON keywordActivated(keyword: Blocker)\n  BIND \"self\"\n  text: \"when this card activates [Blocker]\"\n\n-- §22-5 — when a card evolves into this card\nDEFINE TRIGGER evolvedInto\n  ON keywordActivated(keyword: Evolve)\n  BIND \"subject\"\n  text: \"when a card evolves into this card\"\n\n-- §22-5 — when you use this card's [Evolve] from your hand\nDEFINE TRIGGER evolveFromHandActivated\n  ON keywordActivated(from: hand, keyword: Evolve)\n  BIND \"self\"\n  text: \"when you use this card's [Evolve] from your hand\"\n\n-- §22-13 — when you activate a [Union] skill\nDEFINE TRIGGER unionActivated\n  ON keywordActivated(keyword: Union, watcher: controller)\n  BIND \"subject\"\n  text: \"when you activate a [Union] skill\"\n\n-- §22-13-5 — when this card's [Union-Absorb] is activated\nDEFINE TRIGGER unionAbsorbActivated\n  ON keywordActivated(keyword: \"Union-Absorb\")\n  BIND \"self\"\n  text: \"when this card's [Union-Absorb] is activated\"\n\n-- §22-41 — when you activate an [Overlord] skill\nDEFINE TRIGGER overlordActivated\n  ON keywordActivated(keyword: Overlord, watcher: controller)\n  BIND \"subject\"\n  text: \"when you activate an [Overlord] skill\"\n\n-- §22-15 — when you play a card using [Over Realm]\nDEFINE TRIGGER overRealmPlayed\n  ON keywordActivated(keyword: \"Over Realm\", watcher: controller)\n  BIND \"subject\"\n  text: \"when you play a card using [Over Realm]\"\n\n-- ── skills and counters (9-6, 9-7, 22-10) ──────────────────────────────────\n\n-- §9-7 — when your opponent activates a [Counter] skill\nDEFINE TRIGGER opponentCounter\n  ON skillActivated(kind: counter, watcher: opponent)\n  BIND \"subject\"\n  text: \"when your opponent activates a [Counter] skill\"\n\n-- §12-1-3 — when you activate an Extra Card from your hand. \"Activating an\n-- Extra Card\" is using its [Activate] or [Counter] skill from the hand unless\n-- the card says otherwise, [Field] included (22-3-1), so `from: hand` is the\n-- whole of it; `extra: true` is the card's type, read before it went to the\n-- Drop (12-2-2-2). The Extra is the subject, and what the card says about it\n-- (\"a blue Extra\", BT29-029) is a condition on that subject.\nDEFINE TRIGGER extraActivated\n  ON skillActivated(extra: true, from: hand, watcher: controller)\n  BIND \"subject\"\n  text: \"when you activate an Extra Card from your hand\"\n\n-- §22-10 — when you activate this card's [Counter] from your hand without paying its energy cost\nDEFINE TRIGGER counterFreeFromHand\n  ON skillActivated(from: hand, kind: counter, paid: false)\n  BIND \"self\"\n  text: \"when you activate this card's [Counter] from your hand without paying its energy cost\"\n\n-- ── modes and markers (1-10, 5-13, 22-32, 22-43) ───────────────────────────\n\n-- §1-10-1 — when this card is rested by one of your skills\nDEFINE TRIGGER restedBySkill\n  ON modeSwitched(by: skill, byOpponent: false, mode: rest)\n  BIND \"self\"\n  text: \"when this card is rested by one of your skills\"\n\n-- §1-10-1 — when your skill rests an opponent's card. The printed wording\n-- names their Battle Cards and energy, which is where the legacy engine pends\n-- it, and the skill is the other player's (#157).\nDEFINE TRIGGER restedTheirsBySkill\n  ON modeSwitched(by: skill, byOpponent: true, in: [battle, energy], mode: rest, watcher: opponent)\n  BIND \"subject\"\n  text: \"when your skill rests an opponent's card\"\n\n-- §1-10-2, §23-5-2-4 — when this card is switched to Hidden Mode by one of\n-- your skills. The card is face down by the time it answers, and the pattern\n-- naming `hidden: true` is what lets its front side do so (`matchTriggers`).\nDEFINE TRIGGER hiddenBySkill\n  ON hiddenSwitched(by: skill, byOpponent: false, hidden: true, in: battle)\n  BIND \"self\"\n  text: \"when this card is switched to Hidden Mode by one of your skills\"\n\n-- §1-10-2 — when this card is switched to Revealed Mode, whatever switched it.\n-- In a Battle or Unison Area only: a card's skills are not valid in the\n-- Energy Area (9-1-3-1), though its energy can be switched there.\nDEFINE TRIGGER switchedRevealed\n  ON hiddenSwitched(hidden: false, in: [battle, unison])\n  BIND \"self\"\n  text: \"when this card is switched to Revealed Mode\"\n\n-- §1-10-2, §23-5-2-4 — when this card is switched to Hidden Mode, whatever\n-- switched it; answered by its front side, as `hiddenBySkill` is.\nDEFINE TRIGGER switchedHidden\n  ON hiddenSwitched(hidden: true, in: [battle, unison])\n  BIND \"self\"\n  text: \"when this card is switched to Hidden Mode\"\n\n-- §23-2 — when this card is placed under another card. The pile is a place\n-- of its own, so the card answers there although its skills are not valid\n-- under a card otherwise (23-2-2); the host is the card on top.\nDEFINE TRIGGER placedUnder\n  ON placedUnder(to: under)\n  BIND \"self\"\n  text: \"when this card is placed under a card\"\n\n-- §3-2, §3-3, §3-4 — when this card goes from your deck or hand to the Drop\nDEFINE TRIGGER deckOrHandToDrop\n  ON moved(from: [deck, hand], to: drop)\n  BIND \"self\"\n  text: \"when this card goes from your deck or hand to the Drop\"\n\n-- §3-10 — when one of your skills sends this card from your deck to the Warp\n-- (BT30-106). The skill's card is the subject the program is handed, so \"by\n-- your <Heles> card's skill\" is a condition on it rather than a moment of its\n-- own. Pended by name from a skill's `moveTo`, as `removedFromBattle` is.\nDEFINE TRIGGER deckToWarpBySkill\n  ON moved(by: skill, byOpponent: false, from: deck, to: warp)\n  BIND \"self\"\n  text: \"when one of your skills sends this card from your deck to the Warp\"\n\n-- §22-32-3 — when this card is rested by an [Alliance] skill\nDEFINE TRIGGER restedByAlliance\n  ON modeSwitched(by: Alliance, mode: rest)\n  BIND \"self\"\n  text: \"when this card is rested by an [Alliance] skill\"\n\n-- §5-13 — when a marker is removed from this card\nDEFINE TRIGGER markerRemoved\n  ON markerRemoved\n  BIND \"self\"\n  text: \"when a marker is removed from this card\"\n\n-- §22-43-3 — when you pay a [Spirit Boost] cost from this card\nDEFINE TRIGGER spiritBoostPaid\n  ON markerRemoved(by: \"Spirit Boost\", watcher: controller)\n  BIND \"subject\"\n  text: \"when you pay a [Spirit Boost] cost from this card\"\n\n-- ── areas outside play (3-8, 3-11, 3-13) ───────────────────────────────────\n\n-- §3-8 — when a card goes from your energy to the Drop\nDEFINE TRIGGER energyToDrop\n  ON moved(from: energy, to: drop, watcher: controller)\n  BIND \"subject\"\n  text: \"when a card goes from your energy to the Drop\"\n\n-- §3-11-5 — when your Unison goes to the Drop\nDEFINE TRIGGER unisonToDrop\n  ON moved(from: unison, to: drop)\n  BIND \"self\"\n  text: \"when your Unison goes to the Drop\"\n\n-- §3-13-1 — when this card is added to your Z-Energy\nDEFINE TRIGGER addedToZEnergy\n  ON moved(to: zEnergy)\n  BIND \"self\"\n  text: \"when this card is added to your Z-Energy\"\n\n-- ── the counter windows (4-3, 9-7) ─────────────────────────────────────────\n-- A [Counter] answers to a window rather than to a card's moment, so these\n-- five carry a name a card's WHEN never says. The shape is the same: the\n-- moment as the event that is it.\n\n-- §9-6-6 — the window after a card is played and before it resolves\nDEFINE TRIGGER \"counter:play\"\n  ON counterTiming(watcher: opponent, window: play)\n  BIND \"subject\"\n  text: \"when your opponent plays a card, before it resolves\"\n\n-- §8-1-4 — the window after an attack is declared\nDEFINE TRIGGER \"counter:attack\"\n  ON counterTiming(watcher: opponent, window: attack)\n  BIND \"subject\"\n  text: \"when your opponent declares an attack\"\n\n-- §8-1-4 — the same window, narrowed to an attack a Battle Card made\nDEFINE TRIGGER \"counter:battleCardAttack\"\n  ON counterTiming(attacker: battleCard, watcher: opponent, window: attack)\n  BIND \"subject\"\n  text: \"when your opponent's Battle Card declares an attack\"\n\n-- §9-7-4 — the window after a [Counter] skill is activated\nDEFINE TRIGGER \"counter:counter\"\n  ON counterTiming(watcher: opponent, window: counter)\n  BIND \"subject\"\n  text: \"when your opponent activates a [Counter] skill, before it resolves\"\n\n-- §9-6-6 — the window after a skill is activated\nDEFINE TRIGGER \"counter:skill\"\n  ON counterTiming(watcher: opponent, window: skill)\n  BIND \"subject\"\n  text: \"when your opponent activates a skill, before it resolves\"\n",
  "words.rules": "-- The words a board shows for a zone, a phase or beat, a mode or a colour —\n-- `wording.ts`'s refusals, `narration.ts`'s beats and `lighting.ts`'s room\n-- colours, gathered as `board-words.ts`'s `BoardWords` (Stage 8, #159).\n--\n-- Declared rather than hand-written by the owner's decision on #131/#135\n-- (20 Sep 2026): DEFINE WORDS is a declaration of its own, not a field of\n-- DEFINE GAME. `of:` says which table a word belongs to; the name is the\n-- zone, phase/step, mode or colour it is the word for, so `DEFINE WORDS\n-- battle` is the words for `DEFINE ZONE battle` and needs no second name.\n--\n-- Consumed: `board-words.ts` reads every word below from the loaded\n-- definition (`wordsFromRuleset`, over the generated `files.ts`), and\n-- `wording.ts`, `narration.ts`, `effects.ts` and `lighting.ts` read it from\n-- there (Stage 8, #159). The sentence *shapes* around the words — which branch\n-- a viewer takes, the \"cannot ... now\" frame — stay in those files.\n--\n-- The last three sections are the phrases a `Requirement` and a rule in force\n-- are said in: `of: verb`, `of: window` and `of: until`. Their names carry a\n-- prefix because a name is unique across every `of:` (`charge` is already a\n-- phase, `main` and `defense` too).\n\n-- §3: the twelve areas the manual counts, minus the two effect-language-only\n-- routes (`under`, `play`) `zones.rules` also declares — a program needs to\n-- name them, but a board never shows them as a place a card sits, so\n-- `board-words.ts`'s own tables carry no entry for either and neither does\n-- this file. Order follows `zones.rules`.\nDEFINE WORDS deck\n  of: zone\n  you: \"your deck\"\n  text: \"the deck\"\n\nDEFINE WORDS hand\n  of: zone\n  you: \"your hand\"\n  text: \"hand\"\n\nDEFINE WORDS drop\n  of: zone\n  you: \"your Drop Area\"\n  text: \"the Drop\"\n\nDEFINE WORDS leader\n  of: zone\n  you: \"the Leader Area\"\n  text: \"the Leader Area\"\n\nDEFINE WORDS battle\n  of: zone\n  you: \"your Battle Area\"\n  text: \"the Battle Area\"\n\nDEFINE WORDS combo\n  of: zone\n  you: \"your Combo Area\"\n  text: \"the Combo Area\"\n\nDEFINE WORDS energy\n  of: zone\n  you: \"your Energy Area\"\n  text: \"the Energy Area\"\n\nDEFINE WORDS life\n  of: zone\n  you: \"your Life Area\"\n  text: \"life\"\n\nDEFINE WORDS warp\n  of: zone\n  you: \"your Warp\"\n  text: \"the Warp\"\n\nDEFINE WORDS unison\n  of: zone\n  you: \"the Unison Area\"\n  text: \"the Unison Area\"\n\nDEFINE WORDS zDeck\n  of: zone\n  you: \"your Z-Deck\"\n  text: \"the Z-Deck\"\n\nDEFINE WORDS zEnergy\n  of: zone\n  you: \"your Z-Energy Area\"\n  text: \"Z-Energy\"\n\nDEFINE WORDS removed\n  of: zone\n  you: \"out of the game\"\n  text: \"out of the game\"\n\n-- §6, §7: the six turn phases and the two a turn is not made of (`setup`,\n-- `over`), as `narration.ts`'s beat stream names them, plus the five battle\n-- sub-flow steps a \"phase\" beat also narrates (`declared`..`battleEnd`,\n-- `board-words.ts`'s own `PHASE_DECLARATION` maps each to `game.rules`'s\n-- `mainEnd` or to `battle.rules`'s own step). Order follows `PHASE` there.\nDEFINE WORDS charge\n  of: phase\n  text: \"Charge Phase\"\n\nDEFINE WORDS main\n  of: phase\n  text: \"Main Phase\"\n\nDEFINE WORDS mainEnd\n  of: phase\n  text: \"Main Phase ends\"\n\nDEFINE WORDS end\n  of: phase\n  text: \"End Phase\"\n\nDEFINE WORDS declared\n  of: phase\n  text: \"Attack declared\"\n\nDEFINE WORDS offense\n  of: phase\n  text: \"Offense Step\"\n\nDEFINE WORDS defense\n  of: phase\n  text: \"Defense Step\"\n\nDEFINE WORDS damage\n  of: phase\n  text: \"Damage Step\"\n\nDEFINE WORDS battleEnd\n  of: phase\n  text: \"The battle ends\"\n\nDEFINE WORDS setup\n  of: phase\n  text: \"Setting up\"\n\nDEFINE WORDS over\n  of: phase\n  text: \"The game is over\"\n\n-- §1-10: the only two tokens `zones.rules` declares for a zone's `modes:`.\nDEFINE WORDS active\n  of: mode\n  text: \"Active Mode\"\n\nDEFINE WORDS rest\n  of: mode\n  text: \"Rest Mode\"\n\n-- §1-2-3: the seven colours `attributes.rules`' own `colors` attribute may\n-- hold. `room: true` marks the five a Leader can be, and so a room can be lit\n-- for (`lighting.ts`'s `LEADER_COLOURS`) — White and Colorless light no room\n-- of their own (`colourOf`'s own fallback to Black).\nDEFINE WORDS Red\n  of: color\n  room: true\n  text: \"Red\"\n\nDEFINE WORDS Blue\n  of: color\n  room: true\n  text: \"Blue\"\n\nDEFINE WORDS Green\n  of: color\n  room: true\n  text: \"Green\"\n\nDEFINE WORDS Yellow\n  of: color\n  room: true\n  text: \"Yellow\"\n\nDEFINE WORDS Black\n  of: color\n  room: true\n  text: \"Black\"\n\nDEFINE WORDS White\n  of: color\n  text: \"White\"\n\nDEFINE WORDS Colorless\n  of: color\n  text: \"Colorless\"\n\n-- `wording.ts`'s verb in \"X cannot <verb> now\", one per action a client can\n-- ask for. An action with no word here is said \"do that\" (the shape's own\n-- default).\nDEFINE WORDS verbAttack\n  of: verb\n  text: \"attack\"\n\nDEFINE WORDS verbCombo\n  of: verb\n  text: \"combo\"\n\nDEFINE WORDS verbPlay\n  of: verb\n  text: \"be played\"\n\nDEFINE WORDS verbPlayUnison\n  of: verb\n  text: \"be played\"\n\nDEFINE WORDS verbPlayZ\n  of: verb\n  text: \"be played\"\n\nDEFINE WORDS verbActivate\n  of: verb\n  text: \"use its skill\"\n\nDEFINE WORDS verbCharge\n  of: verb\n  text: \"be charged\"\n\nDEFINE WORDS verbCounter\n  of: verb\n  text: \"counter\"\n\nDEFINE WORDS verbBlock\n  of: verb\n  text: \"block\"\n\nDEFINE WORDS verbChoose\n  of: verb\n  text: \"be chosen\"\n\n-- `wording.ts`'s remedy for a timing refusal: when the action is allowed. A\n-- window with no word here is said \"Only in the <window>.\" by the shape.\nDEFINE WORDS windowMain\n  of: window\n  text: \"Only in your Main Phase.\"\n\nDEFINE WORDS windowBattle\n  of: window\n  text: \"Only during a battle.\"\n\nDEFINE WORDS windowDefense\n  of: window\n  text: \"Only in the Defense Step of your opponent's turn.\"\n\nDEFINE WORDS windowNextTurn\n  of: window\n  text: \"No attacks on the first turn — from your next turn on.\"\n\n-- `effects.ts`'s `untilWords`: how long a rule in force holds, one per\n-- duration. `{them}` is the other player's name and `{source}` the card\n-- holding a rule up. Where the phrase depends on whose turn ends it, `you:`\n-- is the one that names the viewer and `text:` the one that names the other\n-- player; `bare:` is `text:` with no `{source}` to fill.\nDEFINE WORDS untilTurn\n  of: until\n  text: \"until the end of the turn\"\n\nDEFINE WORDS untilBattle\n  of: until\n  text: \"for the battle\"\n\nDEFINE WORDS untilNextTurn\n  of: until\n  you: \"until the start of your next turn\"\n  text: \"until the start of {them}'s next turn\"\n\nDEFINE WORDS untilOpponentTurn\n  of: until\n  you: \"until the start of your next turn\"\n  text: \"until the start of {them}'s next turn\"\n\nDEFINE WORDS untilAfterNextCharge\n  of: until\n  text: \"through the next Charge Phase\"\n\nDEFINE WORDS untilGame\n  of: until\n  text: \"for the rest of the game\"\n\n-- \"…while this card is in a Battle Area\" on an [Auto]/[Activate] effect: ends\n-- as the card that made it leaves the Battle Area.\nDEFINE WORDS untilWhileSourceInPlay\n  of: until\n  text: \"while {source} is in a Battle Area\"\n  bare: \"while its card is in a Battle Area\"\n\nDEFINE WORDS untilPermanent\n  of: until\n  text: \"while {source} is in play\"\n  bare: \"while its card is in play\"\n",
  "zones.rules": "-- The areas of the Dragon Ball Super Card Game, as declarations.\n--\n-- Every section cited is `docs/rules/rulemanual.txt`: §3 is the areas\n-- themselves, §1-10 card positions (Active and Rest Mode), §1-11 markers,\n-- §9-1-3-1 where a card's own skills are valid, §20-10 removal from the game\n-- and §23-2 cards placed under other cards.\n--\n-- The manual counts twelve areas (§3). Three more are declared below because\n-- a program has to be able to name them: `removed` (§20-10, where a card\n-- removed from the game is kept, which the manual pointedly says is no area\n-- at all), `under` (§23-2, the cards beneath another card) and `play`, which\n-- is the word for the three areas together in which a card is in play\n-- (§9-1-3-1). Each says so in its own text.\n--\n-- Three conventions, held to on every declaration so that a reader never has to\n-- ask what a missing line meant:\n--   `ordered: true`  the order of the cards is fixed by the rules and no\n--                    player may rearrange it (§3-2-2, §3-9-2). Every other\n--                    area lets its owner change the order freely, and is\n--                    written `ordered: false` rather than left out.\n--   `visibility`     who may read the faces: `none` is a secret area neither\n--                    player may check, `owner` a secret area its own player\n--                    may read, `all` an open area (§3-1-3).\n--   `place`          is this zone a list of cards a player holds? Twelve of the\n--                    fifteen are, and so are `removed` (§20-10) — a card\n--                    removed from the game is kept somewhere even though the\n--                    manual counts it in no area. `play` and `under` are not:\n--                    the first is a word for three zones at once (§9-1-3-1)\n--                    and the second is the pile hanging off one card\n--                    (§23-2-2-2). An interpreter builds a side's zones from\n--                    the ones that are, so this line is what saves it from\n--                    knowing those two names (#139).\n--\n-- Each player possesses one of every area, and two areas of the same name\n-- with different masters are different areas (§3-1-1) — which is what\n-- `owner: player` says. No area of this game is shared.\n\nDEFINE ZONE deck                                                          -- §3-2\n  owner: player\n  visibility: none\n  ordered: true\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"the deck, face down: neither player may check its contents or change its order (3-2-2)\"\n\nDEFINE ZONE hand                                                          -- §3-3\n  owner: player\n  visibility: owner\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"the cards a player holds: their own to read and reorder, and no limit on how many (3-3-2, 3-3-4)\"\n\nDEFINE ZONE drop                                                          -- §3-4\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"where KO'd Battle Cards, spent Unison Cards and activated Extra Cards are placed, face up (3-4-1, 3-4-3)\"\n\nDEFINE ZONE leader                                                        -- §3-5\n  owner: player\n  visibility: all\n  ordered: false\n  single: true\n  markers: false\n  inPlay: true\n  host: true\n  place: true\n  modes: [active, rest]\n  text: \"the one Leader Card, face up, which no effect or rule may move out of this area (3-5-1, 3-5-3)\"\n\nDEFINE ZONE battle                                                        -- §3-6\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: true\n  host: true\n  place: true\n  modes: [active, rest]\n  text: \"where Battle Cards and some Extra Cards are played, revealed and active, with no limit on how many (3-6-1, 3-6-3)\"\n\nDEFINE ZONE combo                                                         -- §3-7\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: true\n  place: true\n  text: \"the Battle Cards used in a combo, face up (3-7-1, 3-7-2)\"\n\nDEFINE ZONE energy                                                        -- §3-8\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: true\n  inPlay: false\n  host: false\n  place: true\n  modes: [active, rest]\n  text: \"the energy a player pays costs with, face up and active, and where energy markers are kept (3-8-1, 3-8-3, 1-14-3)\"\n\nDEFINE ZONE life                                                          -- §3-9\n  owner: player\n  visibility: none\n  ordered: true\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"the Leader's life, face down: its order may not be changed, but any card may be chosen when one leaves (3-9-2, 3-9-4)\"\n\nDEFINE ZONE warp                                                          -- §3-10\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"where cards sent to the Warp are placed, face up and readable by either player (3-10-2)\"\n\nDEFINE ZONE unison                                                        -- §3-11\n  owner: player\n  visibility: all\n  ordered: false\n  single: true\n  markers: true\n  inPlay: true\n  host: true\n  place: true\n  modes: [active, rest]\n  text: \"the one Unison Card, revealed and active, carrying the markers its skills are counted in (3-11-3, 3-11-4, 1-11-1)\"\n\nDEFINE ZONE zDeck                                                         -- §3-12\n  owner: player\n  visibility: owner\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"the Z-Deck, face down but its owner's to read and reorder; a face-up card in it is in an open area (3-12-2, 3-12-2-1)\"\n\nDEFINE ZONE zEnergy                                                       -- §3-13\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"the Z-Energy a player pays Z-Energy costs with, face up (3-13-2, 3-13-3)\"\n\nDEFINE ZONE removed                                                       -- §20-10\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: true\n  text: \"cards removed from the game: face up, visible to all, and in no area of the game at all (20-10-2, 20-10-3)\"\n\nDEFINE ZONE under                                                         -- §23-2\n  owner: player\n  visibility: all\n  ordered: true\n  single: false\n  markers: false\n  inPlay: false\n  host: false\n  place: false\n  text: \"the cards beneath another card, face up and skills negated; the area they count as being in is the area of the card on top (23-2-2, 23-2-2-2)\"\n\nDEFINE ZONE play                                                          -- §9-1-3-1\n  owner: player\n  visibility: all\n  ordered: false\n  single: false\n  markers: false\n  inPlay: true\n  host: false\n  place: false\n  text: \"not a place a card is put: the word for the Leader, Battle and Unison Areas together, the areas a card's own skills are valid in (9-1-3-1)\"\n",
};
